# ---------------------------------------------------------------------------
# Packaged (.exe) support — PyInstaller sets sys.frozen.  Data files (RFID cards,
# registrations, logs, diagnostics) always live next to the program.
# ---------------------------------------------------------------------------
FROZEN = bool(getattr(sys, 'frozen', False))
APP_DIR = Path(sys.executable).resolve().parent if FROZEN else Path(os.path.abspath(__file__)).parent
if FROZEN:
    os.chdir(APP_DIR)
    for _stream in (sys.stdout, sys.stderr):
        try:
            _stream.reconfigure(encoding='utf-8', errors='replace')
        except (AttributeError, ValueError):
            pass
CONFIG_FILE = APP_DIR / 'csms_config.json'   # {"username", "password", "web_port", "ocpp_port"}


def convert_decimals(obj: Any) -> Any:
    """Recursively convert Decimal objects to float for JSON serialization"""
    if isinstance(obj, Decimal):
        return float(obj)
    elif isinstance(obj, dict):
        return {k: convert_decimals(v) for k, v in obj.items()}
    elif isinstance(obj, (list, tuple)):
        return [convert_decimals(item) for item in obj]
    elif hasattr(obj, '__dict__'):
        # Handle dataclass or object with __dict__
        return convert_decimals(vars(obj))
    else:
        return obj

try:
    import websockets
    from websockets.server import WebSocketServerProtocol
except ImportError:
    print("Please install: pip install websockets")
    exit(1)

