def _logo_png_bytes() -> bytes:
    import base64 as _b64
    return _b64.b64decode(''.join(BPC_LOGO_B64.split()))

# ============================================================================
# Data Classes
# ============================================================================
@dataclass
class Transaction:
    transaction_id: int
    connector_id: int
    id_tag: str
    meter_start: int
    start_time: str
    
@dataclass 
class ChargePointData:
    id: str
    vendor: str = ""
    model: str = ""
    serial_number: str = ""
    firmware_version: str = ""
    status: Dict[int, str] = field(default_factory=dict)
    transactions: Dict[int, dict] = field(default_factory=dict)
    last_heartbeat: str = ""
    connected: bool = True
    registration_status: str = "Pending"  # Accepted, Pending, Rejected
    # --- fleet overview (many stations): what the station table shows per row ---
    error_codes: Dict[int, str] = field(default_factory=dict)   # connector -> errorCode of the last StatusNotification
    meter: Dict[int, dict] = field(default_factory=dict)        # connector -> {power_w, energy_wh, soc, current_a, voltage_v, timestamp}
    last_seen: str = ""                                          # ISO time of the last OCPP message from this CP
    connected_since: str = ""
    disconnected_at: str = ""
    remote_address: str = ""

    def to_dict(self):
        return {
            'id': self.id,
            'vendor': self.vendor,
            'model': self.model,
            'serial_number': self.serial_number,
            'firmware_version': self.firmware_version,
            'status': self.status,
            'transactions': self.transactions,
            'last_heartbeat': self.last_heartbeat,
            'connected': self.connected,
            'registration_status': self.registration_status,
            'error_codes': self.error_codes,
            'meter': self.meter,
            'last_seen': self.last_seen,
            'connected_since': self.connected_since,
            'disconnected_at': self.disconnected_at,
            'remote_address': self.remote_address,
        }


def _empty_station(cp_id: str, registration_status: str = 'Pending') -> dict:
    """Row for a station that is registered but has never connected in this run."""
    return {
        'id': cp_id, 'vendor': '', 'model': '', 'serial_number': '', 'firmware_version': '',
        'status': {}, 'transactions': {}, 'last_heartbeat': '', 'connected': False,
        'registration_status': registration_status, 'error_codes': {}, 'meter': {},
        'last_seen': '', 'connected_since': '', 'disconnected_at': '', 'remote_address': '',
    }

