# ---- switching at runtime + admin API ---------------------------------------------------------------------------
def db_sync_everything(force_files: bool = False):
    """Write every in-memory store to the active backend (used right after switching the database on or off)."""
    g = globals()
    done = []
    try:
        if DB is not None:
            DB.forget_snapshot()                           # everything counts as changed -> full seed of the database
        for name in ('pay_ledger', 'customers'):
            store = g.get(name)
            if store is not None:
                store._dirty = True
                store.flush(force_files=force_files)
                done.append(name)
        for name in ('pay_settings', 'app_settings', 'station_info'):
            store = g.get(name)
            if store is not None:
                store.save(force_files=force_files)
                done.append(name)
        st = g.get('app_state')
        if st is not None and hasattr(st, '_save_rfid_cards'):
            st._save_rfid_cards(force_files=force_files)
            st._save_cp_registrations(force_files=force_files)
            st._save_config_overrides(force_files=force_files)
            done.append('app_state')
    except Exception as e:
        logger.error(f"db: sync failed: {e}")
    return done


def db_apply_settings(new: dict) -> dict:
    """Save database.json and switch the live backend (connect + seed, or back to files). Returns the status."""
    global DB, DB_SETTINGS
    merged = dict(DB_SETTINGS)
    for k in DB_DEFAULTS:
        if k in new:
            merged[k] = new[k]
    if not str(merged.get('uri') or '').strip():
        merged['uri'] = DB_SETTINGS.get('uri', '')       # blank = keep the stored connection string
    merged['type'] = 'mongodb' if str(merged.get('type')) == 'mongodb' else 'json'
    merged['db_name'] = (str(merged.get('db_name') or 'bpc_csms').strip() or 'bpc_csms')[:60]
    try:
        merged['log_retention_days'] = max(1, min(3650, int(merged.get('log_retention_days') or 30)))
    except (TypeError, ValueError):
        merged['log_retention_days'] = 30
    merged['log_to_db'] = bool(merged.get('log_to_db', True))
    merged['keep_json_backup'] = bool(merged.get('keep_json_backup', True))
    if merged['type'] == 'mongodb':
        if not merged['uri']:
            raise ValueError('Connection string is required')
        store = db_connect(merged)                           # raises when unreachable -> nothing changes
        old, DB = DB, store
        DB_SETTINGS = merged
        DB_STATE.update(source='mongodb', error='', fallback=False)
        if old is not None and old is not store:
            old.close()
        db_sync_everything()                                # seed MongoDB with everything the CSMS has in memory
    else:
        old, DB = DB, None
        DB_SETTINGS = merged
        DB_STATE.update(source='json', error='', fallback=False)
        db_sync_everything(force_files=True)                # make sure the JSON files are complete
        if old is not None:
            old.flush(10)
            old.close()
    db_save_settings(merged)
    return db_status()


def db_startup_summary() -> str:
    if DB is not None:
        try:
            c = DB.stats().get('collections', {})
            return "🗄️ Database: MongoDB %s '%s' (payments %s, customers %s, transactions %s, logs %s)%s" % (
                DB.server_version, DB.db_name, c.get('payments'), c.get('customers'), c.get('transactions'), c.get('ocpp_logs'),
                '' if DB_SETTINGS.get('keep_json_backup', True) else ' - JSON backup files off')
        except Exception as e:
            return '🗄️ Database: MongoDB (%s)' % e
    if DB_STATE.get('fallback'):
        return '🗄️ Database: local JSON files (FALLBACK - %s)' % DB_STATE.get('error', '')
    return '🗄️ Database: local JSON files (configure MongoDB in the Database tab)'


def db_status() -> dict:
    s = {'type': DB_SETTINGS.get('type', 'json'), 'source': DB_STATE.get('source', 'json'), 'uri': db_masked_uri(DB_SETTINGS.get('uri', '')),
         'uri_set': bool(DB_SETTINGS.get('uri')), 'db_name': DB_SETTINGS.get('db_name', 'bpc_csms'), 'log_to_db': bool(DB_SETTINGS.get('log_to_db', True)),
         'log_retention_days': DB_SETTINGS.get('log_retention_days', 30), 'keep_json_backup': bool(DB_SETTINGS.get('keep_json_backup', True)),
         'error': DB_STATE.get('error', ''), 'fallback': bool(DB_STATE.get('fallback')), 'pymongo': DB_STATE.get('pymongo', ''),
         'env_uri': bool(os.environ.get('CSMS_MONGODB_URI')), 'settings_file': DB_SETTINGS_FILE, 'connected': False}
    if DB is not None:
        try:
            s.update(DB.stats())
        except Exception as e:
            s['error'] = str(e)[:200]
    return s


def _db_hint(uri: str, err: str) -> str:
    """A plain-language next step for the usual Atlas / MongoDB connection problems ('' when nothing fits)."""
    low = (err or '').lower()
    u = (uri or '').lower()
    if '<db_password>' in u or '<password>' in u:
        return 'Replace <db_password> in the connection string with the password of the database user.'
    if 'must be escaped' in low or 'rfc 3986' in low:
        return 'The password contains special characters - URL-encode them (e.g. @ = %40) or use a password with letters and digits only.'
    if 'bad auth' in low or 'authentication failed' in low or 'auth failed' in low:
        return 'Wrong database user name or password - check Atlas > Database Access (or reset the password there).'
    if 'dns query name does not exist' in low or 'nxdomain' in low or ('no answer' in low and 'dns' in low):
        return 'The cluster address was not found - copy the connection string again from Atlas > Connect > Drivers.'
    if 'tlsv1 alert internal error' in low or 'ssl handshake failed' in low or 'tlsv1_alert_internal_error' in low:
        return 'Atlas refused this computer - add its public IP address in Atlas > Network Access (the access list).'
    if 'timed out' in low or 'serverselectiontimeout' in low or 'timeout' in low:
        return 'No answer from the database server - check the internet connection, firewalls (TCP port 27017) and Atlas > Network Access.'
    return ''


def _db_error_text(uri: str, e: Exception) -> str:
    text = '%s: %s' % (type(e).__name__, str(e)[:300])
    hint = _db_hint(uri, text)
    return (hint + ' (' + text + ')') if hint else text


def db_test_connection(uri: str, db_name: str) -> dict:
    """Ping a MongoDB (used by the 'Test connection' button) - runs in a worker thread."""
    try:
        import pymongo
    except Exception:
        return {'ok': False, 'error': 'pymongo is not installed on the CSMS computer (pip install "pymongo[srv]")'}
    t0 = _db_time.time()
    try:
        store = MongoStore(uri, db_name or 'bpc_csms', DB_SETTINGS.get('log_retention_days') or 30, timeout_ms=8000, light=True)
        counts = {c: store.count(c) for c in DB_COLLECTIONS}
        store.close()
        return {'ok': True, 'server_version': store.server_version, 'collections': counts,
                'connect_ms': store.connect_ms, 'total_ms': int(1000 * (_db_time.time() - t0))}
    except Exception as e:
        return {'ok': False, 'error': _db_error_text(uri, e), 'total_ms': int(1000 * (_db_time.time() - t0))}


async def handle_db_status(request):
    loop = asyncio.get_running_loop()
    return web.json_response(await loop.run_in_executor(None, db_status))


async def handle_db_test(request):
    try:
        data = await request.json()
    except Exception:
        return web.json_response({'ok': False, 'error': 'Invalid request'}, status=400)
    uri = str(data.get('uri') or '').strip() or DB_SETTINGS.get('uri', '')
    if not uri:
        return web.json_response({'ok': False, 'error': 'Connection string is required'}, status=400)
    loop = asyncio.get_running_loop()
    res = await loop.run_in_executor(None, db_test_connection, uri, str(data.get('db_name') or 'bpc_csms'))
    return web.json_response(res, status=200 if res.get('ok') else 400)


async def handle_db_settings(request):
    if request.method == 'GET':
        loop = asyncio.get_running_loop()
        return web.json_response(await loop.run_in_executor(None, db_status))
    try:
        data = await request.json()
    except Exception:
        return web.json_response({'error': 'Invalid request'}, status=400)
    loop = asyncio.get_running_loop()
    try:
        status = await loop.run_in_executor(None, db_apply_settings, data)
    except Exception as e:
        uri = str(data.get('uri') or '').strip() or DB_SETTINGS.get('uri', '') if isinstance(data, dict) else ''
        return web.json_response({'error': _db_error_text(uri, e)}, status=400)
    try:
        app_state.add_log('🗄️ DB', 'CSMS', 'DatabaseSettingsChanged', {'type': status.get('type'), 'db_name': status.get('db_name'), 'source': status.get('source')})
    except Exception:
        pass
    return web.json_response(status)


async def handle_db_export(request):
    """Write every store to its JSON file now (a local backup / export of the database)."""
    loop = asyncio.get_running_loop()
    done = await loop.run_in_executor(None, db_sync_everything, True)
    return web.json_response({'ok': True, 'written': done, 'folder': str(APP_DIR) if 'APP_DIR' in globals() else os.getcwd()})


async def handle_db_flush(request):
    loop = asyncio.get_running_loop()
    if DB is not None:
        await loop.run_in_executor(None, DB.flush, 15.0)
    return web.json_response(await loop.run_in_executor(None, db_status))


def db_register_routes(app):
    app.router.add_get('/api/db/status', handle_db_status)
    app.router.add_get('/api/db/settings', handle_db_settings)
    app.router.add_post('/api/db/settings', handle_db_settings)
    app.router.add_post('/api/db/test', handle_db_test)
    app.router.add_post('/api/db/export', handle_db_export)
    app.router.add_post('/api/db/flush', handle_db_flush)


db_startup()


class AppState:
    def __init__(self):
        self.charge_points: Dict[str, 'CentralSystem'] = {}
        self.cp_data: Dict[str, ChargePointData] = {}
        self.web_clients: Set[web.WebSocketResponse] = set()
        self.message_log: List[dict] = []
        self.transaction_counter = 1000
        
        # RFID Card Management
        self.rfid_cards: Dict[str, dict] = {}  # idTag -> {status, expiry_date, parent_id, description}
        self._load_rfid_cards()

        # RemoteStart ที่ operator สั่งจาก CSMS -> ให้ StartTransaction ที่ตามมาได้ Accepted
        # (operator สั่งเอง = authorized) โดยไม่ต้องลง idTag ในรายการบัตร;
        # บัตร RFID ที่ไม่ได้สั่ง remote และไม่ได้ลงทะเบียน ยังโดน Invalid ตามเดิม
        #
        # key = (cp_id, connector_id, idTag.upper()) -> expiry datetime
        # ต้องแยกตาม connector เพราะสั่ง RemoteStart หลายหัวด้วยบัตรใบเดียวกันได้:
        # ถ้า key เป็น idTag เดียว หัวที่ StartTransaction มาก่อนจะ pop ตั๋วไปใช้คนเดียว
        # หัวที่ตามมาจะหาไม่เจอแล้วตกไป authorize_rfid() -> Invalid
        # connector_id = None คือสั่ง RemoteStart โดยไม่ระบุหัว (ปล่อยให้ตู้เลือกเอง)
        self.remote_start_pending: Dict[tuple, datetime] = {}

        # Autocharge (Plug & Charge): ตู้สร้าง idTag เองจาก EVCCID ของรถ = "<prefix><EVCCID>"
        # เลข EVCCID เป็นของรถแต่ละคัน ลงทะเบียนล่วงหน้าไม่ได้ -> auto-accept ตาม prefix แทน
        # ต้องตรงกับ AutochargeIdTagPrefix ฝั่งตู้ (GetConfiguration -> default "AUTO-")
        # ตั้ง autocharge_auto_accept = False เพื่อกลับไปใช้ทะเบียนบัตรอย่างเดียว (เช่นตอนเทส Invalid)
        self.autocharge_auto_accept: bool = True
        self.autocharge_prefix: str = 'AUTO-'

        # [PAYMENT] Pay-by-QR: ตู้สร้าง idTag "PAY-<16 ตัว>" หลังลูกค้าจ่ายผ่าน payment gateway
        # (ลงทะเบียนล่วงหน้าไม่ได้เหมือน autocharge) ตู้ส่ง DataTransfer PaymentReceived มาก่อน
        # Authorize/StartTransaction เสมอ -> เก็บไว้ใน payment_sessions (idTag -> ข้อมูลล่าสุด)
        #   payment_auto_accept = True  : ยอมรับทุก idTag ที่ขึ้นต้นด้วย prefix (เหมือน autocharge) ใช้ตอนทดสอบ
        #   payment_auto_accept = False : ยอมรับเฉพาะ idTag ที่มี PaymentReceived มาแล้ว (เข้มกว่า สำหรับ production)
        self.payment_auto_accept: bool = True
        self.payment_prefix: str = PAYMENT_IDTAG_PREFIX
        self.payment_sessions: Dict[str, dict] = {}

        # CP Registration Management
        self.cp_registrations: Dict[str, str] = {}  # cp_id -> status (Accepted, Pending, Rejected)
        self._load_cp_registrations()
        
        # Default Configuration
        self.default_config = dict(DEFAULT_OCPP_CONFIG)
        self._load_config_overrides() 
    
    def _load_cp_registrations(self):
        """Load CP registrations (database when active, else cp_registrations.json)"""
        def from_file():
            try:
                if os.path.exists('cp_registrations.json'):
                    with open('cp_registrations.json', 'r') as f:
                        return json.load(f)
            except Exception as e:
                logger.error(f"Failed to load CP registrations: {e}")
            return None
        try:
            data, src_ = db_load_doc('settings', 'cp_registrations', from_file)
            self.cp_registrations = {k: v for k, v in (data or {}).items() if isinstance(v, str)}
            logger.info(f"Loaded {len(self.cp_registrations)} CP registrations ({src_})")
        except Exception as e:
            logger.error(f"Failed to load CP registrations: {e}")
            self.cp_registrations = {}

    def _save_cp_registrations(self, force_files: bool = False):
        """Save CP registrations (database + file)"""
        if DB is not None:
            try:
                DB.put_doc('settings', 'cp_registrations', self.cp_registrations)
            except Exception as e:
                logger.error(f"db: saving CP registrations failed: {e}")
        if DB is None or force_files or db_keep_files():
            try:
                with open('cp_registrations.json', 'w') as f:
                    json.dump(self.cp_registrations, f, indent=2)
            except Exception as e:
                logger.error(f"Failed to save CP registrations: {e}")
    
    def get_cp_registration_status(self, cp_id: str) -> str:
        """Get CP registration status, default is Pending for new CPs"""
        return self.cp_registrations.get(cp_id, 'Pending')

    # ---- fleet overview: every station the CSMS knows (registered, connected now, or seen earlier) ----
    def station_record(self, cp_id: str) -> dict:
        data = self.cp_data.get(cp_id)
        if data is None:
            return _empty_station(cp_id, self.cp_registrations.get(cp_id, 'Pending'))
        rec = data.to_dict()
        rec['connected'] = cp_id in self.charge_points
        rec['registration_status'] = self.cp_registrations.get(cp_id, rec.get('registration_status') or 'Pending')
        return rec

    def station_records(self) -> list:
        ids = list(self.cp_registrations.keys())
        ids += [cp_id for cp_id in self.cp_data.keys() if cp_id not in self.cp_registrations]
        ids += [cp_id for cp_id in self.charge_points.keys() if cp_id not in self.cp_registrations and cp_id not in self.cp_data]
        return [self.station_record(cp_id) for cp_id in ids]
    
    def set_cp_registration_status(self, cp_id: str, status: str) -> bool:
        """Set CP registration status"""
        if status not in ['Accepted', 'Pending', 'Rejected']:
            return False
        self.cp_registrations[cp_id] = status
        self._save_cp_registrations()
        return True
    
    def remove_cp_registration(self, cp_id: str) -> bool:
        """Remove CP registration"""
        if cp_id in self.cp_registrations:
            del self.cp_registrations[cp_id]
            self._save_cp_registrations()
            return True
        return False
    
    def _load_config_overrides(self):
        """Load saved config overrides (database when active, else config_overrides.json)"""
        def from_file():
            try:
                if os.path.exists('config_overrides.json'):
                    with open('config_overrides.json', 'r') as f:
                        return json.load(f)
            except Exception as e:
                logger.error(f"Failed to load config overrides: {e}")
            return None
        try:
            overrides, src_ = db_load_doc('settings', 'config_overrides', from_file)
            overrides = overrides or {}
            for key, value in overrides.items():
                if key in self.default_config:
                    self.default_config[key]['value'] = str(value)
            if overrides:
                logger.info(f"Loaded {len(overrides)} config overrides ({src_})")
        except Exception as e:
            logger.error(f"Failed to load config overrides: {e}")

    def _save_config_overrides(self, force_files: bool = False):
        """Save config overrides (database + file)"""
        overrides = {
            key: info['value']
            for key, info in self.default_config.items()
            if not info.get('readonly', False)
        }
        if DB is not None:
            try:
                DB.put_doc('settings', 'config_overrides', overrides)
            except Exception as e:
                logger.error(f"db: saving config overrides failed: {e}")
        if DB is None or force_files or db_keep_files():
            try:
                with open('config_overrides.json', 'w') as f:
                    json.dump(overrides, f, indent=2)
            except Exception as e:
                logger.error(f"Failed to save config overrides: {e}")
    
    def _load_rfid_cards(self):
        """Load RFID cards (database when active, else rfid_cards.json)"""
        def from_file():
            try:
                if os.path.exists('rfid_cards.json'):
                    with open('rfid_cards.json', 'r') as f:
                        return json.load(f)
            except Exception as e:
                logger.error(f"Failed to load RFID cards: {e}")
            return {}
        try:
            cards, src_ = db_load_collection('rfid_cards', from_file)
            self.rfid_cards = {k: v for k, v in (cards or {}).items() if isinstance(v, dict)}
            logger.info(f"Loaded {len(self.rfid_cards)} RFID cards ({src_})")
        except Exception as e:
            logger.error(f"Failed to load RFID cards: {e}")
            self.rfid_cards = {}

    def _save_rfid_cards(self, force_files: bool = False):
        """Save RFID cards (database + file)"""
        if DB is not None:
            try:
                DB.sync_collection('rfid_cards', self.rfid_cards)
            except Exception as e:
                logger.error(f"db: saving RFID cards failed: {e}")
        if DB is None or force_files or db_keep_files():
            try:
                with open('rfid_cards.json', 'w') as f:
                    json.dump(self.rfid_cards, f, indent=2)
            except Exception as e:
                logger.error(f"Failed to save RFID cards: {e}")
    
    def add_rfid_card(self, id_tag: str, status: str = 'Accepted', 
                      expiry_date: str = None, parent_id: str = None,
                      description: str = '') -> bool:
        """Add or update RFID card"""
        self.rfid_cards[id_tag.upper()] = {
            'status': status,
            'expiry_date': expiry_date,
            'parent_id': parent_id,
            'description': description,
            'created_at': datetime.now().isoformat(),
            'last_used': None
        }
        self._save_rfid_cards()
        return True
    
    def remove_rfid_card(self, id_tag: str) -> bool:
        """Remove RFID card"""
        if id_tag.upper() in self.rfid_cards:
            del self.rfid_cards[id_tag.upper()]
            self._save_rfid_cards()
            return True
        return False
    
    def get_rfid_card(self, id_tag: str) -> Optional[dict]:
        """Get RFID card info"""
        return self.rfid_cards.get(id_tag.upper())
    
    def authorize_rfid(self, id_tag: str) -> dict:
        """Authorize RFID card and return IdTagInfo"""
        key = id_tag.upper()
        card = self.rfid_cards.get(key)

        # ตู้ส่ง idTag เป็น reverse hex ของเลขบัตร → ลองเทียบรูปแบบสลับ byte ด้วย
        # ทำให้ลงทะเบียนใน CSMS ด้วยเลขพิมพ์บนบัตร หรือเลข reverse ก็ได้ (match ทั้งคู่)
        if card is None:
            rev = reverse_hex_bytes(key)
            if rev != key:
                card = self.rfid_cards.get(rev)

        if card:
            # Update last used
            card['last_used'] = datetime.now().isoformat()
            self._save_rfid_cards()
            
            # Check expiry
            if card.get('expiry_date'):
                try:
                    expiry = datetime.fromisoformat(card['expiry_date'].replace('Z', '+00:00'))
                    if expiry < datetime.now(timezone.utc):
                        return {
                            'status': AuthorizationStatus.expired,
                            'expiryDate': card['expiry_date']
                        }
                except:
                    pass
            
            result = {'status': card['status']}
            if card.get('expiry_date'):
                result['expiryDate'] = card['expiry_date']
            if card.get('parent_id'):
                result['parentIdTag'] = card['parent_id']
            return result
        
        # Autocharge (Plug & Charge): ตู้สร้าง idTag เองจาก EVCCID ของรถ เป็น "<prefix><EVCCID>"
        # (ฝั่งตู้: OCPP_V38.py _make_autocharge_idtag() ใช้ AutochargeIdTagPrefix_cfg default "AUTO-")
        # เลข EVCCID เป็นของรถแต่ละคัน ลงทะเบียนล่วงหน้าไม่ได้ -> ถ้าไม่ auto-accept ตรงนี้
        # autocharge จะเริ่มชาร์จไม่ได้เลย เพราะไม่มีบัตรใบนี้ในทะเบียน
        # NB: จำกัดเฉพาะ prefix นี้เท่านั้น บัตรมั่ว/บัตรไม่ลงทะเบียนอื่น ๆ ยังได้ Invalid ตามเดิม
        #     (กันไม่ให้ไปพังเทสข้อที่ต้องการ Invalid จริง ๆ)
        if self.autocharge_auto_accept and key.startswith(self.autocharge_prefix.upper()):
            logger.info(f"authorize_rfid: idTag={key} = autocharge ({self.autocharge_prefix}*) -> Accepted")
            return {'status': AuthorizationStatus.accepted}

        # [PAYMENT] Pay-by-QR: idTag "PAY-…" ที่ตู้สร้างหลังลูกค้าจ่ายเงินแล้ว (ดู payment_sessions)
        # ใช้ทั้ง Authorize.req และ StartTransaction.req — ตู้บังคับว่า StartTransaction.conf
        # ต้อง Accepted ไม่งั้นจะ abort แล้วตั้ง refund PENDING ทั้งที่ลูกค้าจ่ายไปแล้ว
        if key.startswith(self.payment_prefix.upper()):
            # [PAYMENT] sessions paid through the CSMS pay page (ledger) decide first
            _ledger_info = pay_authorize(key)
            if _ledger_info is not None:
                logger.info(f"authorize_rfid: idTag={key} = prepaid session -> {_ledger_info['status']}")
                return _ledger_info
            ticket = self.payment_sessions.get(key)
            if ticket is not None or self.payment_auto_accept:
                paid = (f"paid {ticket.get('paidAmount') or ticket.get('amount')} {ticket.get('currency', 'THB')}"
                        if ticket else 'prefix only, no PaymentReceived yet')
                logger.info(f"authorize_rfid: idTag={key} = pay-by-QR ({self.payment_prefix}*) {paid} -> Accepted")
                return {'status': AuthorizationStatus.accepted}
            logger.info(f"authorize_rfid: idTag={key} pay-by-QR without PaymentReceived -> Invalid")
            return {'status': AuthorizationStatus.invalid}

        # Card not found - reject: บัตรที่ไม่ได้ลงทะเบียนใน CSMS = ไม่อนุญาต
        # (ใช้กับทั้งเริ่มชาร์จและหยุดชาร์จ — บัตรมั่ว/บัตรอื่นจะหยุดชาร์จของคนอื่นไม่ได้)
        logger.info(f"authorize_rfid: idTag={id_tag.upper()} not registered -> Invalid")
        return {'status': AuthorizationStatus.invalid}

    def record_payment_event(self, cp_id: str, message_id: str, data) -> Optional[dict]:
        """[PAYMENT] เก็บข้อมูลจาก DataTransfer PaymentReceived/PaymentSettled ของตู้

        data เป็น JSON string (หรือ object) ฟิลด์หลัก: connectorId, sessionId, state, idTag,
        invoiceNo, gateway, providerRef, amount, paidAmount, paidRef, paidAt, currency, tariff,
        tariffMode, budgetKwh, budgetMinutes, transactionId, usedKwh, usedMinutes, usedAmount,
        remainingAmount, refundStatus, refundAmount, refundRef, endReason
        คืน entry ล่าสุดของ idTag นั้น (None ถ้า data อ่านไม่ได้) — ไม่ raise เพราะตู้แค่ต้องการ Accepted
        """
        try:
            payload = json.loads(data) if isinstance(data, str) else dict(data or {})
        except (TypeError, ValueError):
            logger.warning(f"payment: {message_id} from {cp_id} carries non-JSON data: {str(data)[:120]}")
            return None
        if not isinstance(payload, dict):
            return None
        key = str(payload.get('idTag') or '').strip().upper()
        if not key:
            logger.warning(f"payment: {message_id} from {cp_id} has no idTag: {payload}")
            return None
        entry = self.payment_sessions.setdefault(key, {
            'cp_id': cp_id,
            'first_seen': datetime.now().isoformat(),
        })
        entry.update(payload)
        entry['cp_id'] = cp_id
        entry['last_message'] = message_id
        entry['last_seen'] = datetime.now().isoformat()
        # กันโตไม่จำกัด: เก็บไว้ ~500 รายการล่าสุด (ประวัติเต็มดูจาก message log / payment_history.jsonl บนตู้)
        if len(self.payment_sessions) > 500:
            oldest = sorted(self.payment_sessions, key=lambda k: self.payment_sessions[k].get('last_seen', ''))[:100]
            for old in oldest:
                self.payment_sessions.pop(old, None)
        logger.info(
            f"payment: {message_id} cp={cp_id} C{payload.get('connectorId')} idTag={key} "
            f"state={payload.get('state')} paid={payload.get('paidAmount') or payload.get('amount')} "
            f"{payload.get('currency', 'THB')} gateway={payload.get('gateway')} ref={payload.get('paidRef')} "
            f"txn={payload.get('transactionId')} usedKwh={payload.get('usedKwh')} "
            f"usedAmount={payload.get('usedAmount')} refund={payload.get('refundStatus') or '-'} "
            f"end={payload.get('endReason') or '-'}")
        return entry

    def prune_remote_start_pending(self):
        """ทิ้งตั๋ว RemoteStart ที่หมดอายุแล้ว (ตู้ไม่เคยส่ง StartTransaction ตามมา)"""
        now = datetime.now()
        for key in [k for k, exp in self.remote_start_pending.items() if exp <= now]:
            del self.remote_start_pending[key]

    def take_remote_start_pending(self, cp_id: str, connector_id, id_tag: str) -> bool:
        """ใช้ตั๋ว RemoteStart ของหัวนี้ (ถ้ามีและยังไม่หมดอายุ) -> True

        หาตั๋วของหัวที่ระบุก่อน ถ้าไม่มีจึงใช้ตั๋วที่สั่งแบบไม่ระบุหัว (connector_id=None)
        แต่ละหัวมีตั๋วของตัวเอง จึงสั่ง RemoteStart หลายหัวด้วยบัตรใบเดียวกันได้
        """
        self.prune_remote_start_pending()
        key = str(id_tag).upper()
        try:
            cid = int(connector_id)
        except (TypeError, ValueError):
            cid = None
        for k in ((cp_id, cid, key), (cp_id, None, key)):
            if self.remote_start_pending.pop(k, None) is not None:
                return True
        return False

    def next_transaction_id(self) -> int:
        self.transaction_counter += 1
        return self.transaction_counter
        
    async def broadcast(self, msg_type: str, data: dict):
        """Broadcast to all web clients"""
        message = json.dumps({'type': msg_type, 'data': data})
        dead_clients = set()
        for ws in self.web_clients:
            try:
                await ws.send_str(message)
            except:
                dead_clients.add(ws)
        self.web_clients -= dead_clients
        
    def add_log(self, direction: str, cp_id: str, action: str, data: dict = None):
        """Add message to log"""
        entry = {
            'timestamp': datetime.now().strftime('%H:%M:%S'),
            'full_timestamp': datetime.now().isoformat(),
            'date': datetime.now().strftime('%Y-%m-%d'),
            'direction': direction,
            'cp_id': cp_id,
            'action': action,
            'data': data or {}
        }
        self.message_log.append(entry)
        
        # Also save to persistent log
        self._save_log_entry(entry)
        
        # Keep last 100 messages in memory
        if len(self.message_log) > 100:
            self.message_log = self.message_log[-100:]
        asyncio.create_task(self.broadcast('log', entry))
    
    def _save_log_entry(self, entry: dict):
        """Append the log entry to the daily log file.

        One JSON object per line (ocpp_logs_YYYY-MM-DD.jsonl): appending is O(1), which matters
        with 50-100 stations sending MeterValues/Heartbeats. (The old format rewrote the whole
        ocpp_logs_YYYY-MM-DD.json array for every message.) Old .json files are still read.
        """
        db_on_log(entry)                                       # [DB] queued insert into ocpp_logs (when active)
        if not db_keep_files():
            return
        try:
            date_str = entry.get('date', datetime.now().strftime('%Y-%m-%d'))
            with open(f'ocpp_logs_{date_str}.jsonl', 'a', encoding='utf-8') as f:
                f.write(json.dumps(entry, ensure_ascii=False, default=str) + '\n')
        except Exception as e:
            logger.error(f"Failed to save log entry: {e}")

    def get_logs_for_date(self, date_str: str) -> list:
        """Logs of a day: from the database when it has that day, else from the local files"""
        return db_logs_for_date(date_str, lambda: self._get_logs_from_files(date_str))

    def get_available_log_dates(self) -> list:
        """Dates with logs (database + local files)"""
        return db_log_dates(self._get_log_dates_from_files())

    def _get_logs_from_files(self, date_str: str) -> list:
        """Get all logs for a specific date (legacy .json array + current .jsonl lines, in order)"""
        logs = []
        log_file = f'ocpp_logs_{date_str}.json'
        if os.path.exists(log_file):
            try:
                with open(log_file, 'r', encoding='utf-8') as f:
                    logs = json.load(f)
            except Exception:
                logs = []
        jsonl_file = f'ocpp_logs_{date_str}.jsonl'
        if os.path.exists(jsonl_file):
            try:
                with open(jsonl_file, 'r', encoding='utf-8') as f:
                    for line in f:
                        line = line.strip()
                        if line:
                            try:
                                logs.append(json.loads(line))
                            except ValueError:
                                continue
            except Exception:
                pass
        return logs

    def _get_log_dates_from_files(self) -> list:
        """Get list of dates that have logs"""
        dates = set()
        for f in os.listdir('.'):
            if f.startswith('ocpp_logs_') and (f.endswith('.json') or f.endswith('.jsonl')):
                dates.add(f.replace('ocpp_logs_', '').replace('.jsonl', '').replace('.json', ''))
        return sorted(dates, reverse=True)
    
    def export_logs_to_excel(self, date_str: str = None, cp_id: str = None) -> str:
        """Export logs to Excel file"""
        try:
            from openpyxl import Workbook
            from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
            from openpyxl.utils import get_column_letter
        except ImportError:
            # If openpyxl not available, create CSV instead
            return self._export_logs_to_csv(date_str, cp_id)
        
        # Get logs
        if date_str:
            logs = self.get_logs_for_date(date_str)
        else:
            # Get today's logs
            date_str = datetime.now().strftime('%Y-%m-%d')
            logs = self.get_logs_for_date(date_str)
        
        # Filter by CP if specified
        if cp_id:
            logs = [l for l in logs if l.get('cp_id') == cp_id]
        
        if not logs:
            return None
        
        # Create workbook
        wb = Workbook()
        ws = wb.active
        ws.title = "OCPP Logs"
        
        # Define styles
        header_font = Font(bold=True, color="FFFFFF")
        header_fill = PatternFill(start_color="4472C4", end_color="4472C4", fill_type="solid")
        in_fill = PatternFill(start_color="E2EFDA", end_color="E2EFDA", fill_type="solid")
        out_fill = PatternFill(start_color="FCE4D6", end_color="FCE4D6", fill_type="solid")
        thin_border = Border(
            left=Side(style='thin'),
            right=Side(style='thin'),
            top=Side(style='thin'),
            bottom=Side(style='thin')
        )
        
        # Headers
        headers = ['Date', 'Time', 'Direction', 'Charge Point', 'Action', 'Data']
        for col, header in enumerate(headers, 1):
            cell = ws.cell(row=1, column=col, value=header)
            cell.font = header_font
            cell.fill = header_fill
            cell.alignment = Alignment(horizontal='center')
            cell.border = thin_border
        
        # Data rows
        for row, log in enumerate(logs, 2):
            ws.cell(row=row, column=1, value=log.get('date', '')).border = thin_border
            ws.cell(row=row, column=2, value=log.get('timestamp', '')).border = thin_border
            
            direction_cell = ws.cell(row=row, column=3, value=log.get('direction', ''))
            direction_cell.border = thin_border
            if '⬅️' in log.get('direction', ''):
                direction_cell.fill = in_fill
            elif '➡️' in log.get('direction', ''):
                direction_cell.fill = out_fill
            
            ws.cell(row=row, column=4, value=log.get('cp_id', '')).border = thin_border
            ws.cell(row=row, column=5, value=log.get('action', '')).border = thin_border
            
            data_str = json.dumps(log.get('data', {}), ensure_ascii=False, default=str)
            ws.cell(row=row, column=6, value=data_str).border = thin_border
        
        # Adjust column widths
        ws.column_dimensions['A'].width = 12
        ws.column_dimensions['B'].width = 10
        ws.column_dimensions['C'].width = 12
        ws.column_dimensions['D'].width = 15
        ws.column_dimensions['E'].width = 25
        ws.column_dimensions['F'].width = 80
        
        # Add summary sheet
        ws_summary = wb.create_sheet("Summary")
        ws_summary.cell(row=1, column=1, value="OCPP Log Summary").font = Font(bold=True, size=14)
        ws_summary.cell(row=2, column=1, value=f"Date: {date_str}")
        ws_summary.cell(row=3, column=1, value=f"Total Messages: {len(logs)}")
        ws_summary.cell(row=4, column=1, value=f"Charge Point Filter: {cp_id or 'All'}")
        ws_summary.cell(row=5, column=1, value=f"Generated: {datetime.now().isoformat()}")
        
        # Count by action
        action_counts = {}
        cp_counts = {}
        for log in logs:
            action = log.get('action', 'Unknown')
            action_counts[action] = action_counts.get(action, 0) + 1
            cp = log.get('cp_id', 'Unknown')
            cp_counts[cp] = cp_counts.get(cp, 0) + 1
        
        ws_summary.cell(row=7, column=1, value="Messages by Action:").font = Font(bold=True)
        row = 8
        for action, count in sorted(action_counts.items(), key=lambda x: -x[1]):
            ws_summary.cell(row=row, column=1, value=action)
            ws_summary.cell(row=row, column=2, value=count)
            row += 1
        
        row += 1
        ws_summary.cell(row=row, column=1, value="Messages by Charge Point:").font = Font(bold=True)
        row += 1
        for cp, count in sorted(cp_counts.items(), key=lambda x: -x[1]):
            ws_summary.cell(row=row, column=1, value=cp)
            ws_summary.cell(row=row, column=2, value=count)
            row += 1
        
        # Save file
        filename = f'ocpp_logs_{date_str}'
        if cp_id:
            filename += f'_{cp_id}'
        filename += '.xlsx'
        
        wb.save(filename)
        return filename
    
    def _export_logs_to_csv(self, date_str: str = None, cp_id: str = None) -> str:
        """Fallback: Export logs to CSV if openpyxl not available"""
        import csv
        
        # Get logs
        if date_str:
            logs = self.get_logs_for_date(date_str)
        else:
            date_str = datetime.now().strftime('%Y-%m-%d')
            logs = self.get_logs_for_date(date_str)
        
        # Filter by CP if specified
        if cp_id:
            logs = [l for l in logs if l.get('cp_id') == cp_id]
        
        if not logs:
            return None
        
        filename = f'ocpp_logs_{date_str}'
        if cp_id:
            filename += f'_{cp_id}'
        filename += '.csv'
        
        with open(filename, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            writer.writerow(['Date', 'Time', 'Direction', 'Charge Point', 'Action', 'Data'])
            
            for log in logs:
                writer.writerow([
                    log.get('date', ''),
                    log.get('timestamp', ''),
                    log.get('direction', ''),
                    log.get('cp_id', ''),
                    log.get('action', ''),
                    json.dumps(log.get('data', {}), ensure_ascii=False, default=str)
                ])
        
        return filename

app_state = AppState()

# ============================================================================
# OCPP Central System Handler
# ============================================================================
class CentralSystem(cp):
    def __init__(self, charge_point_id: str, websocket: WebSocketServerProtocol):
        super().__init__(charge_point_id, websocket)
        self.data = ChargePointData(id=charge_point_id)
        # Buffer of MeterValues timestamps received during a transaction, keyed by
        # str(transaction_id) -> {context: [timestamp_str, ...]}. Used by Test 5 to
        # verify the charger sends samples at the configured interval.
        self._mv_interval_buffer: Dict[str, Dict[str, list]] = {}
        
    async def _notify_update(self):
        """Notify web clients of CP update"""
        await app_state.broadcast('cp_update', self.data.to_dict())

    async def route_message(self, raw_msg):
        # every message from the CP counts as "seen" (shown as "last seen" in the station table)
        self.data.last_seen = datetime.now().isoformat(timespec='seconds')
        return await super().route_message(raw_msg)

    @on(Action.boot_notification)
    async def on_boot_notification(self, charge_point_vendor: str, charge_point_model: str, **kwargs):
        self.data.vendor = charge_point_vendor
        self.data.model = charge_point_model
        self.data.serial_number = kwargs.get('charge_point_serial_number', '')
        self.data.firmware_version = kwargs.get('firmware_version', '')
        
        # Get registration status from database
        reg_status = app_state.get_cp_registration_status(self.id)
        self.data.registration_status = reg_status
        
        # Map to OCPP RegistrationStatus
        status_map = {
            'Accepted': RegistrationStatus.accepted,
            'Pending': RegistrationStatus.pending,
            'Rejected': RegistrationStatus.rejected
        }
        ocpp_status = status_map.get(reg_status, RegistrationStatus.pending)
        
        # Set interval based on status
        # Rejected/Pending: short interval so CP retries frequently
        # interval = 30 if reg_status == 'Accepted' else 60
        # อ่าน interval จาก config แต่ละสถานะ
        try:
            if reg_status == 'Accepted':
                interval = int(app_state.default_config.get(
                    'BootNotificationAcceptedInterval', {}).get('value', 30))
            elif reg_status == 'Pending':
                interval = int(app_state.default_config.get(
                    'BootNotificationPendingInterval', {}).get('value', 60))
            else:  # Rejected
                interval = int(app_state.default_config.get(
                    'BootNotificationRejectedInterval', {}).get('value', 60))
        except Exception:
            interval = 30 if reg_status == 'Accepted' else 60

        
        app_state.add_log('⬅️ IN', self.id, 'BootNotification', {
            'vendor': charge_point_vendor,
            'model': charge_point_model,
            'registration': reg_status
        })
        
        await self._notify_update()
        
        return call_result.BootNotification(
            current_time=datetime.now(timezone.utc).isoformat(),
            interval=interval,
            status=ocpp_status
        )

    @on(Action.heartbeat)
    async def on_heartbeat(self):
        self.data.last_heartbeat = datetime.now().strftime('%H:%M:%S')
        app_state.add_log('⬅️ IN', self.id, 'Heartbeat')
        await self._notify_update()
        return call_result.Heartbeat(
            current_time=datetime.now(timezone.utc).isoformat()
        )

    @on(Action.status_notification)
    async def on_status_notification(self, connector_id: int, error_code: str, status: str, **kwargs):
        self.data.status[connector_id] = status
        vendor_error = kwargs.get('vendor_error_code') or ''
        self.data.error_codes[connector_id] = (error_code or 'NoError') + (f' ({vendor_error})' if vendor_error and error_code != 'NoError' else '')
        if status not in ('Charging', 'SuspendedEV', 'SuspendedEVSE', 'Finishing') and connector_id in self.data.meter:
            self.data.meter[connector_id]['power_w'] = 0.0          # no session on this connector -> no power
        app_state.add_log('⬅️ IN', self.id, 'StatusNotification', {
            'connector': connector_id,
            'status': status,
            'error': error_code
        })
        await self._notify_update()
        return call_result.StatusNotification()

    @on(Action.authorize)
    async def on_authorize(self, id_tag: str, **kwargs):
        # Use RFID card database for authorization
        id_tag_info = app_state.authorize_rfid(id_tag)
        
        app_state.add_log('⬅️ IN', self.id, 'Authorize', {
            'idTag': id_tag,
            'result': str(id_tag_info.get('status', 'Unknown'))
        })
        
        return call_result.Authorize(id_tag_info=id_tag_info)

    @on(Action.start_transaction)
    async def on_start_transaction(self, connector_id: int, id_tag: str, meter_start: int, timestamp: str, **kwargs):
        # Authorize the idTag
        # ถ้า transaction นี้เกิดจาก RemoteStart ที่ operator สั่งจาก CSMS -> Accepted (authorized โดย operator)
        # ไม่งั้นตรวจตามรายการบัตรปกติ (บัตรไม่ลงทะเบียน = Invalid ตามเดิม)
        _rs_key = str(id_tag).upper()
        if app_state.take_remote_start_pending(self.id, connector_id, id_tag):
            id_tag_info = {'status': AuthorizationStatus.accepted}
            logger.info(f"StartTransaction C{connector_id} idTag={_rs_key}: "
                        f"Accepted (CSMS-initiated RemoteStart)")
        else:
            id_tag_info = app_state.authorize_rfid(id_tag)
        
        txn_id = app_state.next_transaction_id()

        # A connector can only have one active transaction at a time. Drop any stale
        # entry still parked on this connector so Remote Stop never targets an old id.
        for stale_id in [tid for tid, t in self.data.transactions.items()
                         if t.get('connector_id') == connector_id]:
            del self.data.transactions[stale_id]
            self._mv_interval_buffer.pop(str(stale_id), None)

        self.data.transactions[txn_id] = {
            'connector_id': connector_id,
            'id_tag': id_tag,
            'meter_start': meter_start,
            'start_time': timestamp
        }

        # Start a fresh MeterValues interval buffer for this transaction (Test 5)
        self._mv_interval_buffer[str(txn_id)] = {}

        # [PAYMENT] link the transaction to its prepaid session (idTag PAY-...)
        if str(id_tag_info.get('status', '')).split('.')[-1].lower() == 'accepted':
            await pay_on_start_transaction(self.id, connector_id, id_tag, txn_id, meter_start, timestamp)
        db_on_transaction_start(self.id, connector_id, id_tag, txn_id, meter_start, timestamp)   # [DB]

        app_state.add_log('⬅️ IN', self.id, 'StartTransaction', {
            'connector': connector_id,
            'idTag': id_tag,
            'txnId': txn_id,
            'meterStart': meter_start,
            'meterContext': 'Transaction.Begin',  # Implicit context
            'authStatus': str(id_tag_info.get('status', 'Accepted'))
        })
        
        await self._notify_update()
        
        return call_result.StartTransaction(
            transaction_id=txn_id,
            id_tag_info=id_tag_info
        )

    def _check_stoptxn_aligned_interval(self, transaction_id, txn_meter_values: list) -> Optional[list]:
        """Verify the charger sent MeterValues at the configured interval during the
        transaction: ClockAlignedDataInterval for Sample.Clock,
        MeterValueSampleInterval for Sample.Periodic.

        Timestamps come from two sources merged per context:
          1. MeterValues.req sent during the transaction (buffered live) — this is
             where most chargers put periodic/aligned samples.
          2. StopTransaction.req transactionData (some chargers bundle them here).
        """
        interval_by_context = {
            'Sample.Clock': 'ClockAlignedDataInterval',
            'Sample.Periodic': 'MeterValueSampleInterval',
        }

        # Collect timestamps per context from both sources
        timestamps_by_context: Dict[str, set] = {ctx: set() for ctx in interval_by_context}

        # Source 1: live buffer of MeterValues during this transaction
        buffered = self._mv_interval_buffer.get(str(transaction_id), {})
        for ctx, ts_list in buffered.items():
            if ctx in timestamps_by_context:
                timestamps_by_context[ctx].update(t for t in ts_list if t)

        # Source 2: transactionData carried in StopTransaction.req
        for mv in txn_meter_values or []:
            ctx = mv.get('context')
            ts = mv.get('timestamp')
            if ctx in timestamps_by_context and ts:
                timestamps_by_context[ctx].add(ts)

        results = []
        for context, config_key in interval_by_context.items():
            try:
                expected_interval = int(app_state.default_config.get(config_key, {}).get('value', 0) or 0)
            except (TypeError, ValueError):
                expected_interval = 0

            timestamps = sorted(timestamps_by_context[context])
            sample_count = len(timestamps)

            # Not enough data to measure an interval for this context
            if sample_count < 2:
                if expected_interval > 0:
                    # Interval is configured but we saw <2 samples — report as inconclusive
                    results.append({
                        'context': context,
                        'configKey': config_key,
                        'expectedIntervalSec': expected_interval,
                        'sampleCount': sample_count,
                        'observedGapsSec': [],
                        'matched': None,
                        'note': 'ข้อมูลไม่พอ (ต้องมี timestamp อย่างน้อย 2 จุด)'
                    })
                continue

            parsed = []
            for ts in timestamps:
                try:
                    parsed.append(datetime.fromisoformat(ts.replace('Z', '+00:00')))
                except ValueError:
                    pass
            parsed.sort()
            if len(parsed) < 2:
                continue

            gaps = [
                round((parsed[i + 1] - parsed[i]).total_seconds())
                for i in range(len(parsed) - 1)
            ]

            tolerance = 2  # seconds, allow send/clock jitter
            mismatched_gaps = [g for g in gaps if abs(g - expected_interval) > tolerance]

            entry = {
                'context': context,
                'configKey': config_key,
                'expectedIntervalSec': expected_interval,
                'sampleCount': sample_count,
                'observedGapsSec': gaps,
                'mismatchedGapsSec': mismatched_gaps,
            }
            if expected_interval > 0:
                entry['matched'] = len(mismatched_gaps) == 0
            else:
                # Charger sent samples for a context whose interval is disabled (0)
                entry['matched'] = None
                entry['note'] = f'{config_key}=0 (ปิดอยู่) แต่ charger ยังส่ง {context}'
            results.append(entry)

        return results or None

    @on(Action.stop_transaction)
    async def on_stop_transaction(self, meter_stop: int, timestamp: str, transaction_id: int, **kwargs):
        reason = kwargs.get('reason', 'Local')
        transaction_data = kwargs.get('transaction_data', [])

        energy = 0
        if transaction_id in self.data.transactions:
            txn = self.data.transactions[transaction_id]
            energy = meter_stop - txn['meter_start']
            snap = self.data.meter.setdefault(txn.get('connector_id', 0), {})
            snap['power_w'] = 0.0                                   # session over -> no power on this connector
            snap['energy_wh'] = float(meter_stop)
            del self.data.transactions[transaction_id]

        # [PAYMENT] settle the prepaid session of this transaction (used / remaining / refund due)
        await pay_on_stop_transaction(self.id, transaction_id, meter_stop, reason, energy)
        db_on_transaction_stop(self.id, transaction_id, meter_stop, reason, energy, timestamp)   # [DB]

        # Parse transaction_data for meter values with context + timestamp
        txn_meter_values = []
        if transaction_data:
            for mv in transaction_data:
                mv_timestamp = mv.get('timestamp', '')
                for sv in mv.get('sampledValue', mv.get('sampled_value', [])):
                    txn_meter_values.append({
                        'timestamp': mv_timestamp,
                        'measurand': sv.get('measurand', 'Energy.Active.Import.Register'),
                        'value': sv.get('value', '0'),
                        'unit': sv.get('unit', ''),
                        'context': sv.get('context', 'Transaction.End'),
                        'location': sv.get('location', 'Outlet')
                    })

        # Test 5: verify the charger sent MeterValues (Sample.Periodic / Sample.Clock)
        # at the configured interval during this transaction. Uses timestamps buffered
        # from live MeterValues.req plus any carried in transactionData.
        aligned_test = self._check_stoptxn_aligned_interval(transaction_id, txn_meter_values)

        # Done with this transaction's interval buffer
        self._mv_interval_buffer.pop(str(transaction_id), None)

        log_data = {
            'txnId': transaction_id,
            'meterStop': meter_stop,
            'meterContext': 'Transaction.End',  # Implicit context
            'energy': f"{energy} Wh",
            'reason': reason
        }

        if txn_meter_values:
            log_data['transactionData'] = txn_meter_values
        if aligned_test:
            log_data['stopTxnAlignedTest'] = aligned_test

        app_state.add_log('⬅️ IN', self.id, 'StopTransaction', log_data)
        
        await self._notify_update()
        
        return call_result.StopTransaction(
            id_tag_info={'status': AuthorizationStatus.accepted}
        )

    @on(Action.meter_values)
    async def on_meter_values(self, connector_id: int, meter_value: list, **kwargs):
        # Extract key values with context and location
        values = []
        transaction_id = kwargs.get('transaction_id')
        meter_changed = False
        
        for mv in meter_value:
            timestamp = mv.get('timestamp', '')
            mv_contexts = set()
            for sv in mv.get('sampledValue', mv.get('sampled_value', [])):
                measurand = sv.get('measurand', 'Energy.Active.Import.Register')
                value = sv.get('value', '0')
                unit = sv.get('unit', '')
                context = sv.get('context', 'Sample.Periodic')  # Default per OCPP 1.6
                location = sv.get('location', 'Outlet')  # Default per OCPP 1.6
                phase = sv.get('phase', '')
                mv_contexts.add(context)

                values.append({
                    'measurand': measurand,
                    'value': value,
                    'unit': unit,
                    'context': context,
                    'location': location,
                    'phase': phase
                })

            # Buffer this MeterValues timestamp per context for the active
            # transaction, so Test 5 can verify send intervals at StopTransaction.
            # (Charger sends Sample.Periodic/Sample.Clock as separate MeterValues.req
            #  during the transaction, not bundled into StopTransaction.transactionData.)
            if transaction_id is not None and timestamp:
                buf = self._mv_interval_buffer.setdefault(str(transaction_id), {})
                for ctx in mv_contexts:
                    if ctx in ('Sample.Periodic', 'Sample.Clock'):
                        buf.setdefault(ctx, []).append(timestamp)
        
        # Create summary for log
        summary = {}
        contexts_found = set()
        locations_found = set()
        
        for v in values:
            key = v['measurand']
            if v['phase']:
                key += f".{v['phase']}"
            summary[key] = f"{v['value']} {v['unit']}"
            contexts_found.add(v['context'])
            locations_found.add(v['location'])
        
        app_state.add_log('⬅️ IN', self.id, 'MeterValues', {
            'connector': connector_id,
            'txnId': transaction_id,
            'contexts': list(contexts_found),
            'locations': list(locations_found),
            'values': summary,
            'details': values  # Full details for inspection
        })

        # Snapshot for the fleet overview (power / energy / SoC per connector)
        snap = dict(self.data.meter.get(connector_id, {}))
        for v in values:
            if v['phase']:
                continue                                    # per-phase values: keep the totals only
            try:
                val = float(v['value'])
            except (TypeError, ValueError):
                continue
            unit = str(v['unit'] or '').lower()
            m = v['measurand']
            if m == 'Power.Active.Import':
                snap['power_w'] = val * 1000.0 if unit == 'kw' else val
            elif m == 'Energy.Active.Import.Register':
                snap['energy_wh'] = val * 1000.0 if unit == 'kwh' else val
            elif m == 'SoC':
                snap['soc'] = val
            elif m == 'Current.Import':
                snap['current_a'] = val
            elif m == 'Voltage':
                snap['voltage_v'] = val
        snap['timestamp'] = (meter_value[-1].get('timestamp', '') if meter_value else '') or datetime.now().isoformat(timespec='seconds')
        self.data.meter[connector_id] = snap
        meter_changed = True

        # [PAYMENT] prepaid budget: energy used -> amount used; RemoteStop when the budget is used up
        _pay_txn = transaction_id if transaction_id is not None else next((tid for tid, t in self.data.transactions.items() if t.get('connector_id') == connector_id), None)
        await pay_on_meter_values(self.id, connector_id, _pay_txn, snap.get('energy_wh'), snap.get('power_w'))
        db_on_transaction_meter(self.id, _pay_txn, snap.get('energy_wh'), snap.get('power_w'), snap.get('soc'))   # [DB]

        # Reconcile transaction tracking with the CP's ground truth. On reconnect a
        # fresh CentralSystem is created with an empty transactions dict while the CP
        # is still mid-transaction and keeps sending its real active transactionId in
        # MeterValues. Without this, Remote Stop can't find the id (or the frontend's
        # stale id no longer matches the CP) → "หยุดไม่ได้". Trust the CP's id.
        if transaction_id is not None and transaction_id not in self.data.transactions:
            # Drop any stale/divergent entry still parked on this connector
            for stale_id in [tid for tid, t in self.data.transactions.items()
                             if t.get('connector_id') == connector_id]:
                del self.data.transactions[stale_id]
            # Rebuild a minimal active-transaction record from what the CP reported
            meter_now = 0
            for v in values:
                if v['measurand'] == 'Energy.Active.Import.Register':
                    try:
                        meter_now = int(float(v['value']))
                    except (TypeError, ValueError):
                        meter_now = 0
                    break
            self.data.transactions[transaction_id] = {
                'connector_id': connector_id,
                'id_tag': '',
                'meter_start': meter_now,
                'start_time': timestamp or '',
                'reconstructed': True,  # not started via this CSMS session
            }
            meter_changed = True
        if meter_changed:
            await self._notify_update()

        return call_result.MeterValues()

    @on(Action.data_transfer)
    async def on_data_transfer(self, vendor_id: str, **kwargs):
        message_id = kwargs.get('message_id', '')
        data = kwargs.get('data', '')
        app_state.add_log('⬅️ IN', self.id, 'DataTransfer', {
            'vendor': vendor_id,
            'message': message_id,
            'data': data
        })
        # [PAYMENT] ตู้แจ้งผลชำระเงิน (PaymentReceived มาก่อน Authorize) / ผลสรุป (PaymentSettled)
        # เก็บไว้ให้ authorize_rfid() และ log อ่านง่าย — ตอบ Accepted เสมอ ตู้ไม่ block ถ้าตอบอื่น
        if vendor_id == PAYMENT_VENDOR_ID and message_id in PAYMENT_MESSAGE_IDS:
            entry = app_state.record_payment_event(self.id, message_id, data)
            await pay_on_charger_event(self.id, message_id, entry)   # [PAYMENT] charger-terminal payments share the ledger
            if entry is not None:
                # log ซ้ำอีกบรรทัดแบบอ่านง่าย (action = PaymentReceived/PaymentSettled) ให้กรองใน UI ได้
                app_state.add_log('⬅️ IN', self.id, message_id, {
                    'connector': entry.get('connectorId'),
                    'idTag': entry.get('idTag'),
                    'state': entry.get('state'),
                    'gateway': entry.get('gateway'),
                    'invoiceNo': entry.get('invoiceNo'),
                    'paidAmount': entry.get('paidAmount') or entry.get('amount'),
                    'currency': entry.get('currency', 'THB'),
                    'paidRef': entry.get('paidRef'),
                    'txnId': entry.get('transactionId'),
                    'usedKwh': entry.get('usedKwh'),
                    'usedAmount': entry.get('usedAmount'),
                    'remainingAmount': entry.get('remainingAmount'),
                    'refundStatus': entry.get('refundStatus'),
                    'endReason': entry.get('endReason'),
                })
        return call_result.DataTransfer(status='Accepted')

