    async def cmd_get_configuration(
            self,
            keys: list = None,
            mode: str = 'standard'
        ):
            """
            GetConfiguration รองรับ 3 กรณี

            1. OCPP Standard
            ไม่ส่ง field "key"
            Payload:
            {}

            2. Legacy / PEA CSMS compatibility
            ส่ง:
            {
                "key": [""]
            }

            3. Specific keys
            ส่ง key ที่ระบุมาโดยตรง เช่น:
            {
                "key": ["HeartbeatInterval"]
            }
            """

            mode = str(mode or 'standard').strip().lower()

            # ---------------------------------------------------------
            # CASE 1: มีการระบุ key เจาะจง
            # ---------------------------------------------------------
            if keys:
                request_keys = list(keys)

                log_payload = {
                    'key': request_keys
                }

                app_state.add_log(
                    '➡️ OUT',
                    self.id,
                    'GetConfiguration',
                    log_payload
                )

                response = await self.call(
                    call.GetConfiguration(
                        key=request_keys
                    )
                )

            # ---------------------------------------------------------
            # CASE 2: Legacy / PEA style
            # ส่ง {"key":[""]}
            # ---------------------------------------------------------
            elif mode == 'blank-key':
                request_keys = [""]

                log_payload = {
                    'key': request_keys
                }

                app_state.add_log(
                    '➡️ OUT',
                    self.id,
                    'GetConfiguration',
                    log_payload
                )

                response = await self.call(
                    call.GetConfiguration(
                        key=request_keys
                    )
                )

            # ---------------------------------------------------------
            # CASE 3: OCPP 1.6 Standard
            # ไม่ส่ง field key
            # ---------------------------------------------------------
            else:
                log_payload = {}

                app_state.add_log(
                    '➡️ OUT',
                    self.id,
                    'GetConfiguration',
                    log_payload
                )

                response = await self.call(
                    call.GetConfiguration()
                )

            # ---------------------------------------------------------
            # Parse response
            # ---------------------------------------------------------
            config = []

            if (
                hasattr(response, 'configuration_key')
                and response.configuration_key
            ):
                for item in response.configuration_key:

                    key = item.get(
                        'key',
                        item.get('Key', '')
                    )

                    value = item.get(
                        'value',
                        item.get('Value', '')
                    )

                    config.append({
                        'key': key,
                        'value': value,
                        'readonly': item.get(
                            'readonly',
                            item.get('Readonly', False)
                        )
                    })

                    # Sync charger actual value -> CSMS local mirror
                    if (
                        key in app_state.default_config
                        and value is not None
                    ):
                        app_state.default_config[key]['value'] = str(value)

            return {
                'configuration': config,
                'mode': mode
            }

    async def cmd_change_configuration(self, key: str, value: str):
        app_state.add_log('➡️ OUT', self.id, 'ChangeConfiguration', {'key': key, 'value': value})
        response = await self.call(call.ChangeConfiguration(key=key, value=value))
        return {'status': str(response.status)}
    
    # ส่ง ChangeConfiguration ไป Charger + บันทึกใน default_config ด้วย
    async def cmd_change_configuration_with_save(self, key, value):
        cfg_entry = app_state.default_config.get(key, {})
        if cfg_entry.get('csms_only', False):
            app_state.default_config[key]['value'] = str(value)
            app_state._save_config_overrides()          # ← บันทึกลงไฟล์ด้วย
            logger.info(f"CSMS config updated locally: {key} = {value}")
            return {'status': 'Accepted'}

        result = await self.cmd_change_configuration(key, value)
        if result.get('status') in ('Accepted', 'RebootRequired'):
            if key in app_state.default_config:
                app_state.default_config[key]['value'] = str(value)
                app_state._save_config_overrides()      # ← บันทึกลงไฟล์ด้วย
        return result

