    async def cmd_reserve_now(self, connector_id: int, id_tag: str, reservation_id: int,
                              expiry_seconds: int = None):
        from datetime import timedelta
        # expiry_seconds: ระยะเวลา (วินาที) ก่อนหมดอายุ; None = default 1 ชั่วโมง (3600s)
        # ตั้งค่าน้อย ๆ เช่น 30 เพื่อเทส auto-expire
        # ค่าติดลบ (เช่น -60) = expiryDate ย้อนไปในอดีต -> ใช้เทสว่า charger ตอบ Rejected
        #   (charger เช็คที่ OCPP_V38.py:3543 `if not exp_dt or exp_dt <= now: status = "Rejected"`)
        #   ค่าติดลบยังผ่าน JSON schema ของ OCPP ได้ เพราะ dateTime ไม่ได้ห้ามเวลาในอดีต
        seconds = expiry_seconds if expiry_seconds is not None else 3600
        expiry = (datetime.now(timezone.utc) + timedelta(seconds=seconds)).isoformat()
        app_state.add_log('➡️ OUT', self.id, 'ReserveNow', {
            'connector': connector_id,
            'idTag': id_tag,
            'reservationId': reservation_id,
            'expiryDate': expiry
        })
        response = await self.call(call.ReserveNow(
            connector_id=connector_id,
            expiry_date=expiry,
            id_tag=id_tag,
            reservation_id=reservation_id
        ))
        return {'status': str(response.status)}

