class ChargerGateway(PayGateway):
    """Payments taken on the charger's own terminal (reported with DataTransfer PaymentReceived)."""
    id = 'charger'
    name = 'Paid at the charger'
    kind = 'charger'

    async def begin(self, rec, cfg, params, settings):
        return {'ok': True, 'state': 'paid'}


PAY_GATEWAYS = {g.id: g for g in (DemoBankGateway(), RmaBfsGateway(), BhutanQrGateway(), ManualGateway(), ChargerGateway())}

pay_settings = PaymentSettings()
pay_ledger = PaymentLedger()
app_state.payment_auto_accept = bool(pay_settings.data.get('accept_unknown_pay_tags', True))

# Extension points used by the customer app (wallet, accounts, push): event hooks + resolvers.
PAY_HOOKS: Dict[str, list] = {}            # event -> [async fn(rec)], events: paid, charging, completed, failed, cancelled, expired
PAY_EXTENSIONS: Dict[str, Any] = {}        # 'resolve_customer': fn(token)->customer|None, 'config_extra': fn(request, pub)->None,
                                           # 'prepare_record': fn(rec, customer, params)->error|None


def pay_add_hook(event: str, fn):
    PAY_HOOKS.setdefault(event, []).append(fn)


async def _pay_run_hooks(event: str, rec: dict):
    for fn in PAY_HOOKS.get(event, []):
        try:
            await fn(rec)
        except Exception as e:
            logger.error(f"payment hook {event} failed for {rec.get('ref')}: {e}")


# ---------------------------------------------------------------------------
# Flow
# ---------------------------------------------------------------------------
def _pay_station_public(cp_id: str) -> dict:
    """Station facts the customer page may see (no vendor data, no log)."""
    rec = app_state.station_record(cp_id)
    status = rec.get('status') or {}
    connectors = sorted(int(k) for k in status.keys() if str(k).isdigit() and int(k) > 0)
    if not connectors:
        connectors = [1, 2]                                     # nothing reported yet (or offline): show the usual two heads
    out = {'id': cp_id, 'connected': bool(rec.get('connected')), 'registration': rec.get('registration_status'),
           'known': cp_id in app_state.cp_registrations or cp_id in app_state.cp_data, 'connectors': []}
    for c in connectors:
        st = status.get(c) or status.get(str(c)) or 'Unknown'
        active = pay_ledger.active_for_connector(cp_id, c)
        txn = any(int(t.get('connector_id') or 0) == c for t in (rec.get('transactions') or {}).values())
        out['connectors'].append({'id': c, 'status': st, 'busy': bool(active) or txn or st in ('Charging', 'SuspendedEV', 'SuspendedEVSE', 'Finishing', 'Faulted', 'Unavailable'),
                                  'pay_ref': active['ref'] if active else None})
    return out


async def pay_broadcast(rec: dict, event: str = 'update'):
    try:
        await app_state.broadcast('payment_update', {'event': event, 'record': pay_ledger.admin_view(rec), 'kpis': pay_ledger.kpis()})
    except Exception as e:
        logger.debug(f"payment: broadcast failed: {e}")


def _pay_log(rec: dict, action: str, extra: dict = None):
    data = {'ref': rec.get('ref'), 'connector': rec.get('connector_id'), 'amount': rec.get('amount'), 'currency': rec.get('currency'),
            'method': rec.get('method'), 'state': rec.get('state')}
    data.update(extra or {})
    app_state.add_log('💳 PAY', rec.get('cp_id') or 'SYSTEM', action, data)


async def pay_set_state(rec: dict, state: str, detail: str = '', event: str = 'update', log_action: str = None, log_data: dict = None):
    pay_ledger.touch(rec, state=state, state_detail=detail or rec.get('state_detail', ''))
    if log_action:
        data = dict(log_data or {})
        if detail:
            data['detail'] = detail
        _pay_log(rec, log_action, data)
    await pay_broadcast(rec, event)
    if event != 'update':
        await _pay_run_hooks(event, rec)


async def pay_mark_paid(rec: dict, paid_ref: str = '', detail: str = ''):
    if rec.get('state') not in ('created', 'awaiting'):
        return
    rec['paid_at'] = _pay_now()
    rec['next'] = ''
    rec.setdefault('gateway', {})['paid_ref'] = paid_ref or rec.get('gateway', {}).get('auth_no', '')
    rec['customer_message'] = ''
    await pay_set_state(rec, 'paid', detail or 'payment received', event='paid', log_action='PaymentReceived',
                        log_data={'paidRef': paid_ref})
    if rec.get('kind', 'charge') != 'charge':
        return                                   # top-ups etc. are finished by their 'paid' hook (wallet credit)
    await pay_try_start(rec)


async def pay_try_start(rec: dict, by: str = 'auto') -> dict:
    """Send RemoteStartTransaction for a paid session (if the station is online)."""
    if rec.get('state') not in ('paid', 'starting'):
        return {'ok': False, 'error': 'session is not waiting to start (%s)' % rec.get('state')}
    cs = app_state.charge_points.get(rec['cp_id'])
    if cs is None:
        pay_ledger.touch(rec, state_detail='paid - station offline, will start when it reconnects')
        await pay_broadcast(rec)
        return {'ok': False, 'error': 'station offline', 'retry': True}
    if app_state.get_cp_registration_status(rec['cp_id']) != 'Accepted':
        pay_ledger.touch(rec, state_detail='paid - station not accepted in the CSMS yet')
        await pay_broadcast(rec)
        return {'ok': False, 'error': 'station not accepted', 'retry': True}
    if int(rec.get('start_attempts') or 0) >= PAY_START_ATTEMPTS and by == 'auto':
        return {'ok': False, 'error': 'too many start attempts'}
    rec['start_attempts'] = int(rec.get('start_attempts') or 0) + 1
    rec['last_start_at'] = _pay_now()
    await pay_set_state(rec, 'starting', 'RemoteStart sent (attempt %d)' % rec['start_attempts'])
    try:
        result = await cs.cmd_remote_start(rec['ref'], rec.get('connector_id') or None)
    except Exception as e:
        result = {'status': 'Error: %s' % e}
    status = str(result.get('status', '')).split('.')[-1].lower()
    if status == 'accepted':
        pay_ledger.touch(rec, state_detail='RemoteStart accepted - waiting for the charger to start')
        await pay_broadcast(rec)
        return {'ok': True}
    await pay_set_state(rec, 'paid', 'RemoteStart %s' % (result.get('status') or 'rejected'), log_action='PaymentStartFailed')
    return {'ok': False, 'error': 'RemoteStart %s' % result.get('status')}


async def pay_stop(rec: dict, reason: str = 'customer') -> dict:
    cs = app_state.charge_points.get(rec['cp_id'])
    txn = rec.get('transaction_id')
    if cs is None or txn is None:
        return {'ok': False, 'error': 'station offline or no transaction'}
    rec['stop_sent_at'] = _pay_now()
    rec['stop_reason'] = reason
    await pay_set_state(rec, 'stopping', 'RemoteStop sent (%s)' % reason, log_action='PaymentStopRequested')
    try:
        result = await cs.cmd_remote_stop(txn)
    except Exception as e:
        result = {'status': 'Error: %s' % e}
    status = str(result.get('status', '')).split('.')[-1].lower()
    if status != 'accepted':
        await pay_set_state(rec, 'charging', 'RemoteStop %s' % result.get('status'))
        return {'ok': False, 'error': 'RemoteStop %s' % result.get('status')}
    return {'ok': True}


def _pay_usage(rec: dict, energy_wh: float = None, now: datetime = None) -> dict:
    """Used kWh / minutes / amount for a charging session (energy from the meter, time from the clock)."""
    meter_start = rec.get('meter_start')
    kwh = float(rec.get('used_kwh') or 0)
    if energy_wh is not None and meter_start is not None:
        kwh = max(0.0, (float(energy_wh) - float(meter_start)) / 1000.0)
    minutes = float(rec.get('used_minutes') or 0)
    started = rec.get('started_at')
    if started:
        try:
            t0 = datetime.fromisoformat(started.replace('Z', '+00:00'))
            if t0.tzinfo is not None:
                t0 = t0.astimezone().replace(tzinfo=None)
            # never below what was already billed (clock jumps must not refund time)
            minutes = max(minutes, ((now or datetime.now()) - t0).total_seconds() / 60.0)
        except ValueError:
            pass
    tariff = rec.get('tariff') or {}
    used = pay_cost(tariff, kwh, minutes)
    amount = float(rec.get('amount') or 0)
    if used > amount and amount > 0:
        used = _pay_money(amount)                           # prepaid: never bill more than what was paid
    return {'used_kwh': round(kwh, 3), 'used_minutes': round(minutes, 1), 'used_amount': used,
            'remaining_amount': _pay_money(max(0.0, amount - used))}


async def pay_on_start_transaction(cp_id: str, connector_id: int, id_tag: str, transaction_id: int, meter_start: int, timestamp: str):
    rec = pay_ledger.find_by_idtag(id_tag)
    if rec is None or rec.get('cp_id') != cp_id:
        return
    if rec.get('state') not in ('paid', 'starting', 'charging'):
        return
    try:
        started = datetime.fromisoformat(str(timestamp).replace('Z', '+00:00'))
        started = started.astimezone().replace(tzinfo=None) if started.tzinfo else started
        if abs((datetime.now() - started).total_seconds()) > 600:
            started = datetime.now()                        # charger clock far off -> use ours
    except ValueError:
        started = datetime.now()
    pay_ledger.touch(rec, transaction_id=transaction_id, meter_start=meter_start, connector_id=int(connector_id),
                     started_at=started.isoformat(timespec='seconds'), used_kwh=0.0, used_minutes=0.0,
                     used_amount=pay_cost(rec.get('tariff') or {}, 0, 0))
    rec['remaining_amount'] = _pay_money(float(rec['amount']) - float(rec['used_amount']))
    await pay_set_state(rec, 'charging', 'charging - transaction %s' % transaction_id, event='charging', log_action='PaymentChargingStarted',
                        log_data={'txnId': transaction_id})


def _pay_projected_next(rec: dict, power_w: float, now: datetime) -> float:
    """Cost the next MeterValues sample would add at the current power (interval = time since the last one)."""
    tariff = rec.get('tariff') or {}
    last = rec.get('last_mv_at') or ''
    interval = 10.0
    if last:
        try:
            interval = max(5.0, min(120.0, (now - datetime.fromisoformat(last)).total_seconds()))
        except ValueError:
            pass
    kwh = max(0.0, float(power_w or 0)) / 1000.0 * interval / 3600.0
    return kwh * float(tariff.get('per_kwh') or 0) + interval / 60.0 * float(tariff.get('per_minute') or 0)


async def pay_on_meter_values(cp_id: str, connector_id: int, transaction_id, energy_wh: float = None, power_w: float = None):
    """Called from the MeterValues handler: update the usage and - when the budget is (about to be) used up -
    schedule the RemoteStop.  The stop is a separate task: an OCPP handler must answer the charger first
    (python-ocpp reads one message at a time, a call() inside the handler would deadlock until it times out)."""
    rec = pay_ledger.find_by_txn(cp_id, transaction_id)
    if rec is None or rec.get('state') not in ('charging', 'stopping'):
        return
    now = datetime.now()
    usage = _pay_usage(rec, energy_wh, now=now)
    changed = any(abs(float(rec.get(k) or 0) - usage[k]) > 0.0005 for k in ('used_kwh', 'used_amount'))
    projected = _pay_projected_next(rec, power_w, now) if rec['state'] == 'charging' else 0.0
    pay_ledger.touch(rec, force=False, last_mv_at=now.isoformat(timespec='seconds'), **usage)
    if rec['state'] == 'charging' and pay_settings.data.get('auto_stop_on_budget', True) \
            and usage['used_amount'] + projected >= float(rec['amount']) - 1e-9:
        rec['auto_stopped'] = True
        asyncio.create_task(pay_stop(rec, 'budget used up'))
        return
    if changed:
        await pay_broadcast(rec)


async def pay_on_stop_transaction(cp_id: str, transaction_id: int, meter_stop: int, reason: str, energy_wh: float):
    rec = pay_ledger.find_by_txn(cp_id, transaction_id)
    if rec is None:
        return
    usage = _pay_usage(rec, meter_stop)
    refund_amt = usage['remaining_amount']
    threshold = float((rec.get('tariff') or {}).get('refund_threshold') or 0)
    refund = {'status': 'none', 'amount': 0.0, 'ref': '', 'at': ''}
    if refund_amt >= max(0.01, threshold):
        gw = PAY_GATEWAYS.get(rec.get('method'))
        try:
            r = await gw.refund(rec, pay_settings.method(rec.get('method')), refund_amt, pay_settings) if gw else {'status': 'due'}
        except Exception as e:
            r = {'status': 'due', 'note': str(e)}
        refund = {'status': r.get('status', 'due'), 'amount': refund_amt, 'ref': r.get('ref', ''), 'at': _pay_now() if r.get('status') == 'done' else '',
                  'note': r.get('note', '')}
    pay_ledger.touch(rec, stopped_at=_pay_now(), stop_reason=rec.get('stop_reason') or reason or '', refund=refund, **usage)
    await pay_set_state(rec, 'completed', 'stopped (%s) - used %s %.2f' % (reason, rec.get('symbol', ''), usage['used_amount']),
                        event='completed', log_action='PaymentSettled',
                        log_data={'usedKwh': usage['used_kwh'], 'usedAmount': usage['used_amount'], 'refund': refund['status'], 'refundAmount': refund['amount']})


async def pay_on_charger_event(cp_id: str, message_id: str, entry: dict):
    """DataTransfer PaymentReceived / PaymentSettled from a charger with its own payment terminal."""
    if not entry:
        return
    id_tag = str(entry.get('idTag') or '').strip().upper()
    if not id_tag:
        return
    rec = pay_ledger.find_by_idtag(id_tag)
    if message_id == 'PaymentReceived':
        if rec is None:
            amount = _pay_money(entry.get('paidAmount') or entry.get('amount') or 0)
            tariff = {'per_kwh': float(entry.get('tariff') or pay_settings.tariff.get('per_kwh') or 0), 'per_minute': 0.0, 'session_fee': 0.0,
                      'refund_threshold': pay_settings.tariff.get('refund_threshold', 1.0)}
            if str(entry.get('tariffMode') or 'kWh').lower().startswith('min'):
                tariff = {'per_kwh': 0.0, 'per_minute': float(entry.get('tariff') or 0), 'session_fee': 0.0, 'refund_threshold': 1.0}
            rec = pay_ledger.create(cp_id, int(entry.get('connectorId') or 0), amount, 'charger', pay_settings, source='charger', ref=id_tag)
            rec['tariff'] = tariff
            rec['budget'] = pay_budget(tariff, amount)
            rec['currency'] = str(entry.get('currency') or rec['currency'])
            rec['symbol'] = 'Nu.' if rec['currency'] == 'BTN' else rec['currency']
        rec['gateway'] = {'charger_gateway': entry.get('gateway'), 'invoice': entry.get('invoiceNo'), 'paid_ref': entry.get('paidRef'),
                          'session_id': entry.get('sessionId'), 'paid_at': entry.get('paidAt')}
        rec['paid_at'] = _pay_now()
        rec['state_detail'] = 'paid on the charger (%s)' % (entry.get('gateway') or 'terminal')
        if rec['state'] in ('created', 'awaiting', 'paid'):
            rec['state'] = 'paid'
        pay_ledger.touch(rec)
        await pay_broadcast(rec, 'paid')
    elif message_id == 'PaymentSettled' and rec is not None:
        usage = {'used_kwh': float(entry.get('usedKwh') or rec.get('used_kwh') or 0), 'used_minutes': float(entry.get('usedMinutes') or rec.get('used_minutes') or 0),
                 'used_amount': _pay_money(entry.get('usedAmount') or rec.get('used_amount') or 0)}
        usage['remaining_amount'] = _pay_money(entry.get('remainingAmount') if entry.get('remainingAmount') is not None else max(0.0, rec['amount'] - usage['used_amount']))
        rs = str(entry.get('refundStatus') or 'None').lower()
        refund = {'status': 'done' if rs in ('done', 'refunded', 'completed') else ('due' if rs in ('pending', 'due') else 'none'),
                  'amount': _pay_money(entry.get('refundAmount') or 0), 'ref': str(entry.get('refundRef') or ''), 'at': _pay_now() if rs in ('done', 'refunded') else ''}
        pay_ledger.touch(rec, stopped_at=rec.get('stopped_at') or _pay_now(), stop_reason=str(entry.get('endReason') or rec.get('stop_reason') or ''),
                         refund=refund, transaction_id=entry.get('transactionId') or rec.get('transaction_id'), **usage)
        if rec['state'] != 'completed':
            await pay_set_state(rec, 'completed', 'settled by the charger', event='completed')
        else:
            await pay_broadcast(rec)


def pay_authorize(id_tag: str) -> Optional[dict]:
    """IdTagInfo for PAY-* idTags from the ledger (None = not known here)."""
    rec = pay_ledger.find_by_idtag(id_tag)
    if rec is None:
        return None
    if rec.get('state') in ('paid', 'starting', 'charging', 'stopping'):
        return {'status': AuthorizationStatus.accepted}
    if rec.get('state') == 'completed':
        return {'status': AuthorizationStatus.accepted}      # StopTransaction / late Authorize of a finished session
    return {'status': AuthorizationStatus.invalid}


async def pay_watchdog_tick(now: datetime = None):
    """One housekeeping pass: expire unpaid sessions, retry starts, time-based budget, stuck stops."""
    now = now or datetime.now()
    for rec in list(pay_ledger.records.values()):
        st = rec.get('state')
        if st in ('created', 'awaiting'):
            exp = rec.get('expires_at') or ''
            if exp and exp < now.isoformat(timespec='seconds'):
                await pay_set_state(rec, 'expired', 'not paid within %d minutes' % (PAY_UNPAID_TTL // 60), event='expired', log_action='PaymentExpired')
        elif st == 'paid':
            last = rec.get('last_start_at') or ''
            if (not last or (now - datetime.fromisoformat(last)).total_seconds() >= PAY_START_RETRY) and rec['cp_id'] in app_state.charge_points:
                await pay_try_start(rec)
        elif st == 'starting':
            last = rec.get('last_start_at') or ''
            if last and (now - datetime.fromisoformat(last)).total_seconds() >= 120:
                await pay_set_state(rec, 'paid', 'charger did not start the transaction - will retry')
        elif st == 'charging':
            usage = _pay_usage(rec, now=now)
            if abs(usage['used_amount'] - float(rec.get('used_amount') or 0)) >= 0.01:
                pay_ledger.touch(rec, force=False, **usage)
                if pay_settings.data.get('auto_stop_on_budget', True) and usage['used_amount'] >= float(rec['amount']) - 1e-9:
                    rec['auto_stopped'] = True
                    await pay_stop(rec, 'budget used up')
                else:
                    await pay_broadcast(rec)
        elif st == 'stopping':
            sent = rec.get('stop_sent_at') or ''
            if sent and (now - datetime.fromisoformat(sent)).total_seconds() >= 90:
                cs = app_state.charge_points.get(rec['cp_id'])
                if cs is not None and rec.get('transaction_id') in cs.data.transactions:
                    await pay_stop(rec, rec.get('stop_reason') or 'retry')
                else:
                    await pay_set_state(rec, 'completed', 'transaction ended (no StopTransaction seen)', event='completed')
    pay_ledger.flush()


async def pay_watchdog():
    """Every 15 s: housekeeping + ledger flush (started from main())."""
    while True:
        try:
            await asyncio.sleep(15)
            await pay_watchdog_tick()
        except asyncio.CancelledError:
            pay_ledger.flush()
            raise
        except Exception as e:
            logger.error(f"payment watchdog: {e}")


# ---------------------------------------------------------------------------
# Rate limiting for the public (no login) endpoints
# ---------------------------------------------------------------------------
_PAY_RATE: Dict[str, list] = {}


def _pay_rate_ok(ip: str, bucket: str, limit: int, window: int = 60) -> bool:
    key = f'{bucket}:{ip}'
    now = time.time()
    hits = [t for t in _PAY_RATE.get(key, []) if now - t < window]
    if len(hits) >= limit:
        _PAY_RATE[key] = hits
        return False
    hits.append(now)
    _PAY_RATE[key] = hits
    if len(_PAY_RATE) > 5000:
        for k in [k for k, v in _PAY_RATE.items() if not v or now - v[-1] > window]:
            _PAY_RATE.pop(k, None)
    return True


def _pay_base_url(request) -> str:
    env_url = os.environ.get('CSMS_PUBLIC_URL', '').strip().rstrip('/')   # [CLOUD] the deployment's own address wins
    if env_url:
        return env_url
    cfg = (pay_settings.data.get('public_base_url') or '').strip().rstrip('/')
    if cfg:
        return cfg
    if TRUST_PROXY:
        proto = (request.headers.get('X-Forwarded-Proto') or request.scheme or 'http').split(',')[0].strip()
        host = (request.headers.get('X-Forwarded-Host') or request.host or '').split(',')[0].strip()
        return f"{proto}://{host}"
    return f"{request.scheme}://{request.host}"


def _pay_customer_rec(request, data: dict = None):
    """Look up a session by ref + token (customer endpoints)."""
    data = data or {}
    ref = str(data.get('ref') or request.match_info.get('ref') or request.query.get('ref') or '').strip().upper()
    token = str(data.get('token') or request.query.get('token') or '')
    rec = pay_ledger.get(ref)
    if rec is None or not _pay_hmac.compare_digest(token, str(rec.get('token') or '')):
        return None
    return rec


