class StationInfo:
    def __init__(self):
        data, _src = _db_load_collection('stations', lambda: _app_json_load(APP_STATION_INFO_FILE, {}) or {})
        self.data: Dict[str, dict] = {k: v for k, v in (data or {}).items() if isinstance(v, dict)}

    def save(self, force_files: bool = False):
        db = _db()
        if db is not None:
            try:
                db.sync_collection('stations', self.data)
            except Exception as e:
                logger.error(f"app: database save failed: {e}")
        if db is None or force_files or _db_keep_files():
            try:
                _app_atomic_write(APP_STATION_INFO_FILE, self.data)
            except Exception as e:
                logger.error(f"app: failed to save {APP_STATION_INFO_FILE}: {e}")

    def set(self, cp_id: str, info: dict):
        cur = dict(self.data.get(cp_id) or {})
        for k in ('name', 'address', 'hours', 'note'):
            if k in info:
                cur[k] = str(info.get(k) or '')[:120]
        for k in ('lat', 'lon', 'max_kw'):
            if k in info:
                try:
                    cur[k] = float(info[k]) if info[k] not in ('', None) else None
                except (TypeError, ValueError):
                    pass
        if 'hidden' in info:
            cur['hidden'] = bool(info['hidden'])
        self.data[cp_id] = cur
        self.save()

    def fill_demo(self) -> int:
        n = 0
        for s in app_state.station_records():
            cp = s['id']
            town = cp.upper().split('-', 1)[1] if '-' in cp else cp.upper()
            town = town.replace(' ', '')
            if town in APP_DEMO_TOWNS and not (self.data.get(cp) or {}).get('lat'):
                lat, lon, name, addr = APP_DEMO_TOWNS[town]
                self.data[cp] = dict(self.data.get(cp) or {}, name=f'BPC {name}', address=addr, lat=lat, lon=lon)
                n += 1
        if n:
            self.save()
        return n


# ---------------------------------------------------------------------------
# Web Push (VAPID + aes128gcm) - needs the "cryptography" package; otherwise in-app notifications only
# ---------------------------------------------------------------------------
def app_push_available() -> bool:
    try:
        from cryptography.hazmat.primitives.asymmetric import ec  # noqa: F401
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM  # noqa: F401
        return True
    except Exception:
        return False


def app_vapid_generate() -> dict:
    try:
        from cryptography.hazmat.primitives import serialization
        from cryptography.hazmat.primitives.asymmetric import ec
        key = ec.generate_private_key(ec.SECP256R1())
        pem = key.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()).decode()
        pub = key.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
        return {'private_pem': pem, 'public_key': _app_b64url(pub)}
    except Exception as e:
        logger.warning(f"app: Web Push disabled (cryptography not available: {e}) - in-app notifications only")
        return {'private_pem': '', 'public_key': ''}


def app_vapid_auth_header(endpoint: str) -> str:
    """Authorization header for a push service: vapid t=<JWT ES256>, k=<public key>."""
    from cryptography.hazmat.primitives import hashes, serialization
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives.asymmetric.utils import decode_dss_signature
    vap = app_settings.data.get('vapid') or {}
    key = serialization.load_pem_private_key(vap['private_pem'].encode(), password=None)
    u = _pay_urlparse.urlparse(endpoint)
    claims = {'aud': f'{u.scheme}://{u.netloc}', 'exp': int(time.time()) + 12 * 3600, 'sub': app_settings.data.get('push_subject') or 'mailto:admin@example.com'}
    header = _app_b64url(json.dumps({'typ': 'JWT', 'alg': 'ES256'}, separators=(',', ':')).encode())
    body = _app_b64url(json.dumps(claims, separators=(',', ':')).encode())
    signing = f'{header}.{body}'.encode()
    der = key.sign(signing, ec.ECDSA(hashes.SHA256()))
    r, s_ = decode_dss_signature(der)
    sig = _app_b64url(r.to_bytes(32, 'big') + s_.to_bytes(32, 'big'))
    return f"vapid t={header}.{body}.{sig}, k={vap['public_key']}"


def app_push_encrypt(sub: dict, payload: bytes) -> bytes:
    """RFC 8291 / RFC 8188 aes128gcm content encoding."""
    from cryptography.hazmat.primitives import hashes, serialization
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    from cryptography.hazmat.primitives.kdf.hkdf import HKDF
    keys = sub.get('keys') or {}
    ua_pub = _app_b64url_decode(keys.get('p256dh', ''))
    auth = _app_b64url_decode(keys.get('auth', ''))
    ua_key = ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), ua_pub)
    as_key = ec.generate_private_key(ec.SECP256R1())
    as_pub = as_key.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
    shared = as_key.exchange(ec.ECDH(), ua_key)
    salt = secrets.token_bytes(16)
    ikm = HKDF(algorithm=hashes.SHA256(), length=32, salt=auth, info=b'WebPush: info\x00' + ua_pub + as_pub).derive(shared)
    cek = HKDF(algorithm=hashes.SHA256(), length=16, salt=salt, info=b'Content-Encoding: aes128gcm\x00').derive(ikm)
    nonce = HKDF(algorithm=hashes.SHA256(), length=12, salt=salt, info=b'Content-Encoding: nonce\x00').derive(ikm)
    record_size = 4096
    ciphertext = AESGCM(cek).encrypt(nonce, payload + b'\x02', None)
    return salt + _app_struct.pack('>I', record_size) + bytes([len(as_pub)]) + as_pub + ciphertext


async def app_push_send_one(sub: dict, data: dict, ttl: int = 86400) -> int:
    """POST one encrypted push message; returns the HTTP status (0 on transport error)."""
    endpoint = sub.get('endpoint') or ''
    try:
        body = app_push_encrypt(sub, json.dumps(data, ensure_ascii=False).encode('utf-8'))
        headers = {'Authorization': app_vapid_auth_header(endpoint), 'Content-Encoding': 'aes128gcm', 'Content-Type': 'application/octet-stream',
                   'TTL': str(ttl), 'Urgency': 'normal'}
        poster = PAY_EXTENSIONS.get('push_poster')          # tests inject a fake poster
        if poster:
            return await poster(endpoint, headers, body)
        timeout = aiohttp.ClientTimeout(total=15)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.post(endpoint, data=body, headers=headers) as resp:
                return resp.status
    except Exception as e:
        logger.warning(f"app: push send failed: {e}")
        return 0


async def app_push_customer(c: dict, data: dict):
    if not (app_settings.data.get('push_enabled') and app_settings.data.get('vapid', {}).get('public_key')):
        return
    subs = list(c.get('push') or [])
    if not subs:
        return
    keep = []
    for sub in subs:
        status = await app_push_send_one(sub, data)
        if status in (404, 410):
            continue                                  # subscription gone
        keep.append(sub)
    if len(keep) != len(subs):
        c['push'] = keep
        customers.save(force=True)


def app_notify(c: dict, title: str, body: str, url: str = '/app/', kind: str = 'info', ref: str = '', push: bool = True):
    """In-app notification (always) + Web Push (when subscribed) - the push is sent in the background."""
    n = customers.notify(c, title, body, url, kind, ref)
    if push:
        try:
            asyncio.get_running_loop().create_task(app_push_customer(c, {'title': title, 'body': body, 'url': url, 'kind': kind, 'ref': ref, 'id': n['id']}))
        except RuntimeError:
            pass
    return n


# ---------------------------------------------------------------------------
# Wallet gateway + membership / promo logic
# ---------------------------------------------------------------------------
class WalletGateway(PayGateway):
    """Pays a charging session from the customer's prepaid balance; the unused rest goes straight back."""
    id = 'wallet'
    name = 'Wallet balance'
    kind = 'wallet'

    async def begin(self, rec, cfg, params, settings):
        c = customers.get(rec.get('customer_id'))
        if c is None:
            return {'ok': False, 'error': 'Please sign in to pay from your wallet', 'fatal': True}
        if float(c.get('balance') or 0) + 1e-9 < float(rec['amount']):
            return {'ok': False, 'error': 'Not enough balance - top up your wallet first (balance %s %.2f)' % (rec.get('symbol', ''), float(c.get('balance') or 0)), 'fatal': True}
        customers.wallet_add(c, 'charge', -float(rec['amount']), rec['ref'], 'Charging %s connector %s' % (rec['cp_id'], rec['connector_id']))
        rec['gateway'] = {'wallet': True, 'auth_no': 'WAL-' + secrets.token_hex(3).upper(), 'paid_at': _pay_now(), 'balance_after': c['balance']}
        return {'ok': True, 'state': 'paid', 'paid_ref': rec['gateway']['auth_no']}

    async def refund(self, rec, cfg, amount, settings):
        c = customers.get(rec.get('customer_id'))
        if c is None:
            return {'status': 'due'}
        customers.wallet_add(c, 'refund', float(amount), rec['ref'], 'Unused amount of %s' % rec['ref'])
        return {'status': 'done', 'ref': 'WAL-RF-' + secrets.token_hex(3).upper(), 'note': 'returned to the wallet'}


def app_promo_check(code: str, c: dict, context: str, amount: float) -> dict:
    """-> {'ok': bool, 'error': str, 'promo': {...}, 'effect': str}"""
    p = app_settings.promo(code)
    if p is None or not p.get('active'):
        return {'ok': False, 'error': 'Unknown or inactive promo code'}
    if p.get('expires') and p['expires'] < datetime.now().strftime('%Y-%m-%d'):
        return {'ok': False, 'error': 'This promo code has expired'}
    if p.get('max_uses') and int(p.get('used') or 0) >= int(p['max_uses']):
        return {'ok': False, 'error': 'This promo code has been used up'}
    if p.get('once_per_customer') and c is not None and p['code'] in (c.get('promos_used') or []):
        return {'ok': False, 'error': 'You have already used this promo code'}
    if float(amount or 0) < float(p.get('min_amount') or 0):
        return {'ok': False, 'error': 'Minimum amount for this code is %s %.0f' % (pay_settings.data.get('currency_symbol', ''), float(p['min_amount']))}
    if context == 'charge' and p['type'] != 'pct':
        return {'ok': False, 'error': 'This code is a top-up bonus, use it when topping up'}
    if context == 'topup' and p['type'] == 'pct':
        return {'ok': False, 'error': 'This code is a charging discount, use it when starting a session'}
    if p['type'] == 'pct':
        effect = '%g %% off this session' % p['value']
    elif p['type'] == 'bonus_amount':
        effect = '+ %s %.0f bonus' % (pay_settings.data.get('currency_symbol', ''), p['value'])
    else:
        effect = '+ %g %% bonus' % p['value']
    return {'ok': True, 'promo': {'code': p['code'], 'type': p['type'], 'value': p['value'], 'note': p.get('note', '')}, 'effect': effect}


def app_promo_consume(code: str, c: dict):
    p = app_settings.promo(code)
    if p is None:
        return
    p['used'] = int(p.get('used') or 0) + 1
    if c is not None:
        p.setdefault('used_by', []).append(c['id'])
        c.setdefault('promos_used', []).append(p['code'])
    app_settings.save()


def app_topup_bonus(amount: float, promo: Optional[dict], c: dict) -> dict:
    """Bonus credited on a top-up: rule table + optional promo."""
    bonus = 0.0
    rule = None
    for b in app_settings.data.get('topup_bonus') or []:
        if amount >= float(b.get('min') or 0) and float(b.get('bonus') or 0) > 0:
            bonus, rule = float(b['bonus']), b
    promo_bonus = 0.0
    if promo:
        if promo['type'] == 'bonus_amount':
            promo_bonus = float(promo['value'])
        elif promo['type'] == 'bonus_pct':
            promo_bonus = _pay_money(amount * float(promo['value']) / 100.0)
    return {'bonus': _pay_money(bonus), 'rule': rule, 'promo_bonus': _pay_money(promo_bonus), 'total': _pay_money(bonus + promo_bonus)}


def app_prepare_record(rec: dict, c: dict, params: dict) -> Optional[str]:
    """Called for every pay record of a signed-in customer: membership discount + promo code (charging sessions)."""
    if rec.get('kind', 'charge') != 'charge':
        return None
    kwh = float((c.get('stats') or {}).get('kwh') or 0)
    tier = app_settings.tier_for(kwh)
    pct = float(tier.get('discount_pct') or 0)
    promo = None
    code = str((params or {}).get('promo') or '').strip().upper()
    if code:
        res = app_promo_check(code, c, 'charge', rec['amount'])
        if not res['ok']:
            return res['error']
        promo = res['promo']
        pct = min(90.0, pct + float(promo['value']))
    if pct > 0:
        t = dict(rec.get('tariff') or {})
        for k in ('per_kwh', 'per_minute'):
            t[k] = round(float(t.get(k) or 0) * (1 - pct / 100.0), 4)
        rec['tariff'] = t
        rec['budget'] = pay_budget(t, rec['amount'])
    rec['discount'] = {'tier': tier.get('name'), 'tier_pct': float(tier.get('discount_pct') or 0), 'promo': promo['code'] if promo else '',
                       'promo_pct': float(promo['value']) if promo else 0.0, 'pct': pct}
    rec['customer']['name'] = c.get('name', '')
    if promo:
        app_promo_consume(promo['code'], c)
    return None


def app_config_extra(request, pub: dict):
    """Adds the wallet method (and the discount) to the public pay config of a signed-in customer."""
    token = request.query.get('customer_token') or (request.headers.get('Authorization', '')[7:].strip() if request.headers.get('Authorization', '').startswith('Bearer ') else '')
    c = customers.resolve(token) if token else None
    if c is None:
        return
    pub['customer'] = customers.public_view(c)
    pub['methods'] = [{'id': 'wallet', 'name': 'Wallet balance (%s %.2f)' % (pub.get('symbol', ''), float(c.get('balance') or 0)), 'kind': 'wallet',
                       'balance': float(c.get('balance') or 0)}] + list(pub.get('methods') or [])


# ---- hooks on payment events
async def app_hook_paid(rec: dict):
    c = customers.get(rec.get('customer_id'))
    if rec.get('kind') == 'topup':
        if c is None:
            return
        amount = float(rec['amount'])
        promo = (rec.get('gateway') or {}).get('promo')
        bonus = app_topup_bonus(amount, promo, c)
        customers.wallet_add(c, 'topup', amount, rec['ref'], 'Top-up via %s' % rec.get('method_name', rec.get('method')))
        if bonus['total'] > 0:
            customers.wallet_add(c, 'bonus', bonus['total'], rec['ref'], 'Top-up bonus' + (' + promo %s' % promo['code'] if promo and bonus['promo_bonus'] else ''))
        if promo:
            app_promo_consume(promo['code'], c)
        pay_ledger.touch(rec, used_amount=amount, remaining_amount=0.0, wallet_bonus=bonus['total'], wallet_balance_after=c['balance'])
        await pay_set_state(rec, 'completed', 'wallet credited (balance %s %.2f)' % (rec.get('symbol', ''), c['balance']), event='topup_done', log_action='WalletTopUp',
                            log_data={'customer': c['id'], 'bonus': bonus['total']})
        app_notify(c, 'Top-up received', '%s %.2f added to your wallet%s. Balance: %s %.2f' % (rec.get('symbol', ''), amount,
                   (' (+ %s %.2f bonus)' % (rec.get('symbol', ''), bonus['total'])) if bonus['total'] else '', rec.get('symbol', ''), c['balance']),
                   '/app/#/wallet', 'wallet', rec['ref'])
        await app_state.broadcast('customer_update', {'customer': customers.admin_view(c)})
    elif c is not None and rec.get('method') != 'wallet':
        app_notify(c, 'Payment confirmed', '%s %.2f for %s connector %s - the charger is being started' % (rec.get('symbol', ''), float(rec['amount']), rec['cp_id'], rec['connector_id']),
                   '/app/#/session/%s' % rec['ref'], 'session', rec['ref'])


async def app_hook_charging(rec: dict):
    c = customers.get(rec.get('customer_id'))
    if c is None:
        return
    app_notify(c, 'Charging started', '%s connector %s is charging your vehicle.' % (rec['cp_id'], rec['connector_id']),
               '/app/#/session/%s' % rec['ref'], 'session', rec['ref'])


async def app_hook_completed(rec: dict):
    c = customers.get(rec.get('customer_id'))
    if c is None or rec.get('kind') == 'topup':
        return
    st = c.setdefault('stats', {'sessions': 0, 'kwh': 0.0, 'spent': 0.0})
    before = app_settings.tier_for(float(st.get('kwh') or 0))
    st['sessions'] = int(st.get('sessions') or 0) + 1
    st['kwh'] = round(float(st.get('kwh') or 0) + float(rec.get('used_kwh') or 0), 3)
    st['spent'] = _pay_money(float(st.get('spent') or 0) + float(rec.get('used_amount') or 0))
    after = app_settings.tier_for(st['kwh'])
    customers.save(force=True)
    rf = rec.get('refund') or {}
    body = 'Used %.2f kWh = %s %.2f.' % (float(rec.get('used_kwh') or 0), rec.get('symbol', ''), float(rec.get('used_amount') or 0))
    if rf.get('status') == 'done' and float(rf.get('amount') or 0) > 0:
        body += ' %s %.2f returned to your wallet.' % (rec.get('symbol', ''), float(rf['amount']))
    elif rf.get('status') == 'due':
        body += ' Refund of %s %.2f will follow.' % (rec.get('symbol', ''), float(rf.get('amount') or 0))
    app_notify(c, 'Charging finished', body, '/app/#/session/%s' % rec['ref'], 'receipt', rec['ref'])
    if after.get('name') != before.get('name'):
        app_notify(c, 'Welcome to %s' % after['name'], 'You now get %g %% off every charging session.' % float(after.get('discount_pct') or 0), '/app/#/account', 'tier')
    await app_state.broadcast('customer_update', {'customer': customers.admin_view(c)})


async def app_hook_failed(rec: dict):
    c = customers.get(rec.get('customer_id'))
    if c is None or rec.get('input_error'):
        return                                   # rejected input (no bank chosen ...) is shown in the form, not as a notification
    if rec.get('method') == 'wallet' and rec.get('state') in ('cancelled', 'failed') and (rec.get('gateway') or {}).get('wallet') and not (rec.get('refund') or {}).get('status') == 'done':
        # a wallet session cancelled before charging: give the money back
        customers.wallet_add(c, 'refund', float(rec['amount']), rec['ref'], 'Session %s %s' % (rec['ref'], rec.get('state')))
        pay_ledger.touch(rec, refund={'status': 'done', 'amount': float(rec['amount']), 'ref': 'WALLET', 'at': _pay_now()})
    app_notify(c, 'Payment %s' % rec.get('state'), rec.get('state_detail') or '', '/app/#/history', 'info', rec['ref'], push=False)


app_settings = AppSettings()
customers = CustomerStore()
station_info = StationInfo()
PAY_GATEWAYS['wallet'] = WalletGateway()
PAY_EXTENSIONS['resolve_customer'] = customers.resolve
PAY_EXTENSIONS['config_extra'] = app_config_extra
PAY_EXTENSIONS['prepare_record'] = app_prepare_record
pay_add_hook('paid', app_hook_paid)
pay_add_hook('charging', app_hook_charging)
pay_add_hook('completed', app_hook_completed)
for _ev in ('failed', 'cancelled', 'expired'):
    pay_add_hook(_ev, app_hook_failed)


# ---------------------------------------------------------------------------
# Map tiles served through the CSMS.  Phones request /app/tiles/z/x/y.png; the CSMS fetches the tile once from the
# configured provider (OpenStreetMap by default) with a proper User-Agent, keeps it on disk for 7 days and in memory,
# never more than 2 downloads at a time - this follows the OSM tile usage policy and works whatever browser / privacy
# settings the customer has (missing Referer or unusual User-Agents get the "Access blocked" tile from OSM).
# ---------------------------------------------------------------------------
def _app_png_gray(size: int = 256, gray: int = 0xe8) -> bytes:
    raw = b''.join(b'\x00' + bytes([gray]) * size for _ in range(size))

    def chunk(tag, data):
        return _app_struct.pack('>I', len(data)) + tag + data + _app_struct.pack('>I', _app_zlib.crc32(tag + data) & 0xffffffff)
    return (b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', _app_struct.pack('>IIBBBBB', size, size, 8, 0, 0, 0, 0))
            + chunk(b'IDAT', _app_zlib.compress(raw, 9)) + chunk(b'IEND', b''))


APP_TILE_BLANK = _app_png_gray()
_app_tile_mem: Dict[str, bytes] = {}           # LRU (dict order)
_app_tile_inflight: Dict[str, Any] = {}
_app_tile_neg: Dict[str, float] = {}           # key -> do not retry before
_app_tile_state = {'sem': None, 'warned': 0.0, 'stores': 0, 'status': ''}


def _app_tile_upstream(z: int, x: int, y: int) -> str:
    tpl = str((app_settings.data.get('map') or {}).get('tile_url') or APP_DEFAULT_SETTINGS['map']['tile_url'])
    return tpl.replace('{z}', str(z)).replace('{x}', str(x)).replace('{y}', str(y)).replace('{s}', 'a').replace('{r}', '')


def _app_tile_ua() -> str:
    contact = str(app_settings.data.get('push_subject') or '').strip()
    return APP_TILE_UA + (' (+%s)' % contact if contact else '')


def _app_tile_path(z: int, x: int, y: int) -> str:
    return os.path.join(APP_TILE_DIR, str(z), str(x), '%d.png' % y)


def _app_tile_remember(key: str, data: bytes):
    _app_tile_mem.pop(key, None)
    _app_tile_mem[key] = data
    while len(_app_tile_mem) > APP_TILE_MEM_MAX:
        _app_tile_mem.pop(next(iter(_app_tile_mem)))


def _app_tile_prune_disk():
    try:
        files = []
        for root, _dirs, names in os.walk(APP_TILE_DIR):
            for n in names:
                if n.endswith('.png'):
                    fp = os.path.join(root, n)
                    try:
                        files.append((os.stat(fp).st_mtime, fp))
                    except OSError:
                        pass
        if len(files) > APP_TILE_DISK_MAX:
            files.sort()
            for _m, fp in files[:len(files) - int(APP_TILE_DISK_MAX * 0.8)]:
                try:
                    os.remove(fp)
                except OSError:
                    pass
    except Exception as e:
        logger.debug(f"tile cache prune failed: {e}")


def _app_tile_wipe_disk():
    try:
        for root, dirs, names in os.walk(APP_TILE_DIR, topdown=False):
            for n in names:
                try:
                    os.remove(os.path.join(root, n))
                except OSError:
                    pass
            for d in dirs:
                try:
                    os.rmdir(os.path.join(root, d))
                except OSError:
                    pass
    except Exception as e:
        logger.debug(f"tile cache wipe failed: {e}")


def app_tile_cache_reset():
    """Called when the tile provider changes: forget everything (the disk cache is wiped in the background)."""
    _app_tile_mem.clear()
    _app_tile_neg.clear()
    _app_tile_state['status'] = ''
    try:
        asyncio.get_running_loop().run_in_executor(None, _app_tile_wipe_disk)
    except RuntimeError:
        _app_tile_wipe_disk()


def _app_tile_store(key: str, path: str, data: bytes):
    _app_tile_remember(key, data)
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = path + '.tmp'
        with open(tmp, 'wb') as f:
            f.write(data)
        os.replace(tmp, path)
    except OSError as e:
        logger.debug(f"tile cache write failed: {e}")
    _app_tile_state['stores'] += 1
    if _app_tile_state['stores'] % 1000 == 0:
        try:
            asyncio.get_running_loop().run_in_executor(None, _app_tile_prune_disk)
        except RuntimeError:
            pass


async def _app_tile_download(key: str, z: int, x: int, y: int, path: str) -> Optional[bytes]:
    url = _app_tile_upstream(z, x, y)
    status, data, err = 0, b'', ''
    try:
        loop = asyncio.get_running_loop()
        if _app_tile_state['sem'] is None or _app_tile_state.get('loop') is not loop:
            _app_tile_state['sem'], _app_tile_state['loop'] = asyncio.Semaphore(2), loop   # OSM policy: max 2 download threads
        async with _app_tile_state['sem']:
            fetch = PAY_EXTENSIONS.get('tile_fetcher')
            if fetch:
                status, data = await fetch(url)
            else:
                timeout = aiohttp.ClientTimeout(total=20)
                async with aiohttp.ClientSession(timeout=timeout) as session:
                    async with session.get(url, headers={'User-Agent': _app_tile_ua(), 'Accept': 'image/png,image/*;q=0.8,*/*;q=0.5'}) as r:
                        status, data = r.status, await r.read()
                        if status == 200 and not str(r.headers.get('Content-Type', '')).startswith('image/'):
                            status, err = 502, 'not an image'
    except Exception as e:
        status, err = 0, str(e)[:120]
    finally:
        _app_tile_inflight.pop(key, None)
    if status == 200 and data:
        _app_tile_store(key, path, data)
        _app_tile_state['status'] = 'ok'
        return data
    _app_tile_neg[key] = time.time() + (600 if status in (401, 403, 404, 410) else 60)
    _app_tile_state['status'] = 'HTTP %s' % status if status else ('error: ' + err)
    if time.time() - _app_tile_state['warned'] > 600:
        _app_tile_state['warned'] = time.time()
        logger.warning('app: map tile provider answered %s for %s - check Customers > App settings > Map tiles URL'
                       % (_app_tile_state['status'], url))
    return None


async def app_tile_get(z: int, x: int, y: int) -> Optional[bytes]:
    key = '%d/%d/%d' % (z, x, y)
    data = _app_tile_mem.get(key)
    if data is not None:
        _app_tile_remember(key, data)
        return data
    path = _app_tile_path(z, x, y)
    try:
        st = os.stat(path)
        if time.time() - st.st_mtime < APP_TILE_MAX_AGE:
            with open(path, 'rb') as f:
                data = f.read()
            if data:
                _app_tile_remember(key, data)
                return data
    except OSError:
        pass
    if _app_tile_neg.get(key, 0) > time.time():
        return None
    fut = _app_tile_inflight.get(key)
    if fut is None:
        fut = asyncio.ensure_future(_app_tile_download(key, z, x, y, path))
        _app_tile_inflight[key] = fut
    return await asyncio.shield(fut)


async def handle_app_tile(request):
    try:
        z, x, y = int(request.match_info['z']), int(request.match_info['x']), int(request.match_info['y'])
    except (TypeError, ValueError, KeyError):
        raise web.HTTPNotFound()
    n = (1 << z) if 0 <= z <= 19 else 0
    if not n or not (0 <= x < n and 0 <= y < n) or not (app_settings.data.get('map') or {}).get('proxy', True):
        raise web.HTTPNotFound()
    data = await app_tile_get(z, x, y)
    if data is None:
        return web.Response(body=APP_TILE_BLANK, content_type='image/png',
                            headers={'Cache-Control': 'no-store', 'X-Tile': 'unavailable'})
    return web.Response(body=data, content_type='image/png',
                        headers={'Cache-Control': 'public, max-age=86400', 'X-Tile': 'ok'})


# ---------------------------------------------------------------------------
# Customer API (public, bearer token)
# ---------------------------------------------------------------------------
def _app_token(request, data: dict = None) -> str:
    h = request.headers.get('Authorization', '')
    if h.startswith('Bearer '):
        return h[7:].strip()
    if data and data.get('token'):
        return str(data['token'])
    return str(request.query.get('token') or '')


def _app_customer(request, data: dict = None) -> Optional[dict]:
    return customers.resolve(_app_token(request, data))


def _app_unauth():
    return web.json_response({'error': 'Please sign in', 'code': 'unauthorized'}, status=401)


def _app_json(data, status=200):
    return web.json_response(data, status=status, dumps=lambda o: json.dumps(o, default=str))


async def _app_body(request) -> dict:
    try:
        d = await request.json()
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def _app_me_payload(c: dict) -> dict:
    active = [pay_ledger.public_view(r) for r in pay_ledger.records.values()
              if r.get('customer_id') == c['id'] and r.get('kind', 'charge') == 'charge' and r.get('state') in PAY_ACTIVE_STATES]
    active.sort(key=lambda r: r.get('created_at', ''), reverse=True)
    for r in active:
        r['token'] = pay_ledger.get(r['ref'])['token']
    return {'customer': customers.public_view(c), 'active': active[:3], 'settings': app_settings.public(),
            'notifications': (c.get('notifications') or [])[:10]}


async def handle_app_register(request):
    if not _pay_rate_ok(_client_ip(request), 'app_register', 20):     # per IP: mobile networks share addresses (CGNAT)
        return web.json_response({'error': 'Too many attempts - please wait a minute'}, status=429)
    d = await _app_body(request)
    name = str(d.get('name') or '').strip()
    phone = _app_norm_phone(d.get('phone'))
    email = str(d.get('email') or '').strip().lower()
    password = str(d.get('password') or '')
    if len(name) < 2:
        return web.json_response({'error': 'Please enter your name'}, status=400)
    if not _pay_re.fullmatch(r'[0-9]{7,15}', phone):
        return web.json_response({'error': 'Please enter a valid mobile number (e.g. 17123456)'}, status=400)
    if email and not _pay_re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', email):
        return web.json_response({'error': 'Please enter a valid e-mail address'}, status=400)
    if len(password) < 6:
        return web.json_response({'error': 'Password must be at least 6 characters'}, status=400)
    if customers.by_login(phone) is not None or (email and customers.by_login(email) is not None):
        return web.json_response({'error': 'An account with this number / e-mail already exists - please sign in'}, status=409)
    c = customers.create(name, phone, password, email, str(d.get('plate') or ''), str(d.get('lang') or 'en'))
    bonus = float(app_settings.data.get('welcome_bonus') or 0)
    if bonus > 0:
        customers.wallet_add(c, 'bonus', bonus, '', 'Welcome bonus')
    customers.notify(c, 'Welcome to %s' % app_settings.data.get('app_name', 'BPC EV'), 'Top up your wallet and find a charger on the map.', '/app/#/map', 'info')
    token = customers.issue_token(c, request.headers.get('User-Agent', ''))
    app_state.add_log('👤 APP', 'SYSTEM', 'CustomerRegistered', {'customer': c['id'], 'name': c['name']})
    await app_state.broadcast('customer_update', {'customer': customers.admin_view(c)})
    out = _app_me_payload(c)
    out['token'] = token
    return _app_json(out)


def _app_login_fail_count(login: str) -> int:
    key = 'app_login_fail:' + login
    now = time.time()
    hits = [t for t in _PAY_RATE.get(key, []) if now - t < APP_LOGIN_FAIL_WINDOW]
    _PAY_RATE[key] = hits
    return len(hits)


async def handle_app_login(request):
    ip = _client_ip(request)
    if not _pay_rate_ok(ip, 'app_login', 30):                              # per IP (shared on mobile networks)
        return web.json_response({'error': 'Too many attempts - please wait a minute'}, status=429)
    d = await _app_body(request)
    login = str(d.get('login') or '').strip().lower()
    if _app_login_fail_count(login) >= APP_LOGIN_FAIL_LIMIT:                # per account: brute-force protection
        return web.json_response({'error': 'Too many wrong passwords - try again in 15 minutes or reset the password'}, status=429)
    c = customers.by_login(login)
    if c is None or not _app_check_password(str(d.get('password') or ''), c.get('password') or {}):
        _PAY_RATE.setdefault('app_login_fail:' + login, []).append(time.time())
        await asyncio.sleep(0.5)
        return web.json_response({'error': 'Wrong number / e-mail or password'}, status=401)
    _PAY_RATE.pop('app_login_fail:' + login, None)
    if c.get('blocked'):
        return web.json_response({'error': 'This account is blocked - please contact support'}, status=403)
    token = customers.issue_token(c, request.headers.get('User-Agent', ''))
    out = _app_me_payload(c)
    out['token'] = token
    return _app_json(out)


async def handle_app_logout(request):
    d = await _app_body(request)
    tok = _app_token(request, d)
    c = customers.resolve(tok)
    if c is not None:
        sub = d.get('endpoint')
        if sub:
            c['push'] = [s for s in c.get('push') or [] if s.get('endpoint') != sub]
            customers.save()
    customers.revoke(tok)
    return _app_json({'ok': True})


async def handle_app_me(request):
    c = _app_customer(request)
    if c is None:
        return _app_unauth()
    if request.method == 'GET':
        return _app_json(_app_me_payload(c))
    d = await _app_body(request)
    if 'name' in d and len(str(d['name']).strip()) >= 2:
        c['name'] = str(d['name']).strip()[:60]
    if 'email' in d:
        email = str(d.get('email') or '').strip().lower()
        if email and not _pay_re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', email):
            return web.json_response({'error': 'Please enter a valid e-mail address'}, status=400)
        other = customers.by_login(email) if email else None
        if other is not None and other['id'] != c['id']:
            return web.json_response({'error': 'This e-mail is used by another account'}, status=409)
        c['email'] = email[:80]
    if 'plate' in d:
        c['plate'] = str(d.get('plate') or '').strip().upper()[:20]
    if d.get('lang') in ('en', 'dz', 'th'):
        c['lang'] = d['lang']
    if d.get('new_password'):
        if not _app_check_password(str(d.get('old_password') or ''), c.get('password') or {}):
            return web.json_response({'error': 'Current password is wrong'}, status=400)
        if len(str(d['new_password'])) < 6:
            return web.json_response({'error': 'Password must be at least 6 characters'}, status=400)
        c['password'] = _app_hash_password(str(d['new_password']))
    customers.save(force=True)
    return _app_json(_app_me_payload(c))


def _app_station_list(c: Optional[dict] = None) -> list:
    out = []
    pct = 0.0
    if c is not None:
        pct = float(app_settings.tier_for(float((c.get('stats') or {}).get('kwh') or 0)).get('discount_pct') or 0)
    t = pay_settings.tariff
    for s in app_state.station_records():
        if s.get('registration_status') != 'Accepted':
            continue
        info = station_info.data.get(s['id']) or {}
        if info.get('hidden'):
            continue
        pub = _pay_station_public(s['id'])
        conns = pub['connectors']
        out.append({'id': s['id'], 'name': info.get('name') or s['id'], 'address': info.get('address') or '', 'hours': info.get('hours') or '',
                    'note': info.get('note') or '', 'lat': info.get('lat'), 'lon': info.get('lon'), 'online': bool(s.get('connected')),
                    'vendor': s.get('vendor') or '', 'model': s.get('model') or '',
                    'connectors': conns, 'free': sum(1 for x in conns if not x['busy'] and x['status'] in ('Available', 'Preparing', 'Unknown')) if s.get('connected') else 0,
                    'max_kw': float(info.get('max_kw') or 0),
                    'price_per_kwh': round(float(t.get('per_kwh') or 0) * (1 - pct / 100.0), 2), 'price_per_minute': round(float(t.get('per_minute') or 0) * (1 - pct / 100.0), 2),
                    'session_fee': float(t.get('session_fee') or 0), 'discount_pct': pct})
    return out


async def handle_app_stations(request):
    c = _app_customer(request)
    return _app_json({'stations': _app_station_list(c), 'map': app_settings.public()['map'], 'symbol': pay_settings.data.get('currency_symbol', 'Nu.')})


async def handle_app_station(request):
    c = _app_customer(request)
    cp_id = request.match_info['cp_id']
    for s in _app_station_list(c):
        if s['id'] == cp_id:
            return _app_json(s)
    return web.json_response({'error': 'Station not found'}, status=404)


async def handle_app_charge(request):
    """Start a wallet-funded charging session (same checks as the public pay page)."""
    c = _app_customer(request)
    if c is None:
        return _app_unauth()
    d = await _app_body(request)
    try:
        amount = _pay_money(d.get('amount'))
    except (TypeError, ValueError):
        amount = 0.0
    if float(c.get('balance') or 0) + 1e-9 < amount:
        return web.json_response({'error': 'Not enough balance - top up your wallet first (balance %s %.2f)' % (pay_settings.data.get('currency_symbol', ''), float(c.get('balance') or 0)),
                                  'code': 'low_balance'}, status=400)
    d['customer_token'] = _app_token(request, d)
    d['method'] = 'wallet'
    fake = _AppReq(request, d)
    return await handle_pay_public_create(fake)


class _AppReq:
    """Wraps a request with a replaced JSON body (used to reuse the public pay handlers)."""

    def __init__(self, request, data: dict):
        self._r = request
        self._d = data
        self.headers = request.headers
        self.query = request.query
        self.match_info = request.match_info
        self.remote = request.remote
        self.scheme = request.scheme
        self.host = request.host
        self.method = 'POST'

    async def json(self):
        return self._d


async def handle_app_topup(request):
    """Top up the wallet with one of the enabled gateways (demo / RMA / Bhutan QR); confirm with the pay endpoints."""
    c = _app_customer(request)
    if c is None:
        return _app_unauth()
    if not _pay_rate_ok(_client_ip(request), 'create', 30):
        return web.json_response({'error': 'Too many requests - please wait a minute'}, status=429)
    d = await _app_body(request)
    try:
        amount = _pay_money(d.get('amount'))
    except (TypeError, ValueError):
        amount = 0.0
    t = pay_settings.tariff
    lo, hi = float(t.get('min_amount') or 0), max(float(t.get('max_amount') or 0) * 4, 20000.0)
    if amount < lo or amount > hi:
        return web.json_response({'error': 'Amount must be between %s and %s' % (int(lo), int(hi))}, status=400)
    method = str(d.get('method') or '')
    if method not in pay_settings.enabled_methods():
        return web.json_response({'error': 'Payment method not available'}, status=400)
    promo = None
    code = str(d.get('promo') or '').strip().upper()
    if code:
        res = app_promo_check(code, c, 'topup', amount)
        if not res['ok']:
            return web.json_response({'error': res['error']}, status=400)
        promo = res['promo']
    rec = pay_ledger.create('', 0, amount, method, pay_settings, source='app', customer={'name': c.get('name', ''), 'ip': _client_ip(request)},
                            extra={'kind': 'topup', 'customer_id': c['id']})
    rec['budget'] = {'kwh': None, 'minutes': None, 'mixed': False}
    gw = PAY_GATEWAYS[method]
    try:
        res = await gw.begin(rec, pay_settings.method(method), d, pay_settings)
    except Exception as e:
        logger.exception('top-up begin failed')
        res = {'ok': False, 'error': 'Gateway error: %s' % e, 'fatal': True}
    if not res.get('ok'):
        rec['input_error'] = True
        await pay_set_state(rec, 'failed', res.get('error', 'failed'), event='failed', log_action='PaymentFailed')
        return web.json_response({'error': res.get('error', 'Top-up failed'), 'ref': rec['ref']}, status=400)
    if promo:
        rec.setdefault('gateway', {})['promo'] = promo
    rec['next'] = res.get('next', '')
    rec['expected_bonus'] = app_topup_bonus(amount, promo, c)['total']
    _pay_log(rec, 'PaymentCreated', {'method': method, 'kind': 'topup', 'customer': c['id']})
    if res.get('state') == 'paid':
        await pay_mark_paid(rec, res.get('paid_ref', ''))
    else:
        await pay_set_state(rec, res.get('state', 'awaiting'), 'waiting for the customer at the gateway', event='created')
    out = pay_ledger.public_view(rec)
    out['token'] = rec['token']
    out['expected_bonus'] = rec['expected_bonus']
    return _app_json(out)


async def handle_app_sessions(request):
    c = _app_customer(request)
    if c is None:
        return _app_unauth()
    recs = [r for r in pay_ledger.records.values() if r.get('customer_id') == c['id'] and not r.get('input_error')][::-1]   # newest first (stable for equal timestamps)
    recs.sort(key=lambda r: r.get('created_at', ''), reverse=True)
    out = []
    for r in recs[:200]:
        v = pay_ledger.public_view(r)
        v['token'] = r['token'] if r.get('state') in PAY_ACTIVE_STATES else ''
        v['wallet_bonus'] = r.get('wallet_bonus')
        v['station_name'] = (station_info.data.get(r.get('cp_id')) or {}).get('name') or r.get('cp_id')
        out.append(v)
    st = c.get('stats') or {}
    return _app_json({'sessions': out, 'stats': st, 'tier': app_settings.tier_for(float(st.get('kwh') or 0))})


async def handle_app_wallet(request):
    c = _app_customer(request)
    if c is None:
        return _app_unauth()
    return _app_json({'balance': float(c.get('balance') or 0), 'entries': list(reversed(c.get('wallet') or []))[:100],
                      'topup_bonus': app_settings.data.get('topup_bonus') or [], 'methods': pay_settings.public()['methods'],
                      'symbol': pay_settings.data.get('currency_symbol', 'Nu.'), 'min_amount': pay_settings.tariff.get('min_amount'),
                      'max_amount': max(float(pay_settings.tariff.get('max_amount') or 0) * 4, 20000.0)})


async def handle_app_notifications(request):
    c = _app_customer(request)
    if c is None:
        return _app_unauth()
    if request.method == 'POST':
        d = await _app_body(request)
        ids = set(d.get('ids') or [])
        for n in c.get('notifications') or []:
            if not ids or n.get('id') in ids:
                n['read'] = True
        customers.save()
    return _app_json({'notifications': c.get('notifications') or [], 'unread': sum(1 for n in c.get('notifications') or [] if not n.get('read'))})


async def handle_app_push_subscribe(request):
    c = _app_customer(request)
    if c is None:
        return _app_unauth()
    d = await _app_body(request)
    sub = d.get('subscription') or {}
    endpoint = str(sub.get('endpoint') or '')
    keys = sub.get('keys') or {}
    if request.path.endswith('/unsubscribe'):
        c['push'] = [s for s in c.get('push') or [] if s.get('endpoint') != endpoint]
        customers.save(force=True)
        return _app_json({'ok': True, 'subscriptions': len(c['push'])})
    if not endpoint.startswith('https://') or not keys.get('p256dh') or not keys.get('auth'):
        return web.json_response({'error': 'Invalid push subscription'}, status=400)
    subs = [s for s in c.get('push') or [] if s.get('endpoint') != endpoint]
    subs.append({'endpoint': endpoint, 'keys': {'p256dh': str(keys['p256dh']), 'auth': str(keys['auth'])}, 'ua': request.headers.get('User-Agent', '')[:120], 'created': _pay_now()})
    c['push'] = subs[-5:]
    customers.save(force=True)
    return _app_json({'ok': True, 'subscriptions': len(c['push'])})


async def handle_app_push_test(request):
    c = _app_customer(request)
    if c is None:
        return _app_unauth()
    if not c.get('push'):
        return web.json_response({'error': 'No push subscription on this account yet'}, status=400)
    n = app_notify(c, 'Test notification', 'Push notifications are working on this device.', '/app/#/account', 'info')
    return _app_json({'ok': True, 'id': n['id']})


async def handle_app_promo_check(request):
    c = _app_customer(request)
    if c is None:
        return _app_unauth()
    d = await _app_body(request)
    res = app_promo_check(str(d.get('code') or ''), c, str(d.get('context') or 'charge'), _pay_money(d.get('amount') or 0))
    return _app_json(res, 200 if res.get('ok') else 400)


