async def handle_app_admin_customers(request):
    q = str(request.query.get('q') or '').strip().lower()
    out = []
    for c in customers.customers.values():
        if q and q not in (c.get('name', '') + ' ' + c.get('phone', '') + ' ' + c.get('email', '') + ' ' + c.get('plate', '') + ' ' + c['id']).lower():
            continue
        out.append(customers.admin_view(c))
    out.sort(key=lambda c: c.get('created_at', ''), reverse=True)
    totals = {'customers': len(customers.customers), 'balance': _pay_money(sum(float(c.get('balance') or 0) for c in customers.customers.values())),
              'push': sum(1 for c in customers.customers.values() if c.get('push'))}
    return _app_json({'customers': out[:500], 'totals': totals})


async def handle_app_admin_customer(request):
    cid = request.match_info['cid']
    c = customers.get(cid)
    if c is None:
        return web.json_response({'error': 'Unknown customer'}, status=404)
    recs = sorted([pay_ledger.admin_view(r) for r in pay_ledger.records.values() if r.get('customer_id') == cid][::-1], key=lambda r: r.get('created_at', ''), reverse=True)
    return _app_json({'customer': customers.admin_view(c), 'wallet': list(reversed(c.get('wallet') or []))[:100], 'sessions': recs[:100],
                      'notifications': (c.get('notifications') or [])[:20], 'push': [{'endpoint': s.get('endpoint', '')[:60] + '…', 'ua': s.get('ua', ''), 'created': s.get('created')} for s in c.get('push') or []]})


async def handle_app_admin_customer_action(request):
    d = await _app_body(request)
    c = customers.get(str(d.get('id') or ''))
    if c is None:
        return web.json_response({'error': 'Unknown customer'}, status=404)
    action = str(d.get('action') or '')
    note = str(d.get('note') or '').strip()[:120]
    if action == 'adjust':
        try:
            amount = _pay_money(d.get('amount'))
        except (TypeError, ValueError):
            return web.json_response({'error': 'Invalid amount'}, status=400)
        if amount == 0:
            return web.json_response({'error': 'Amount must not be zero'}, status=400)
        customers.wallet_add(c, 'adjust', amount, '', note or 'Adjusted by the operator')
        app_notify(c, 'Wallet adjusted', '%s %+.2f (%s). Balance: %s %.2f' % (pay_settings.data.get('currency_symbol', ''), amount, note or 'operator', pay_settings.data.get('currency_symbol', ''), c['balance']), '/app/#/wallet', 'wallet')
        app_state.add_log('👤 APP', 'SYSTEM', 'WalletAdjusted', {'customer': c['id'], 'amount': amount, 'note': note})
    elif action == 'reset_password':
        pw = str(d.get('password') or '')
        if len(pw) < 6:
            return web.json_response({'error': 'Password must be at least 6 characters'}, status=400)
        c['password'] = _app_hash_password(pw)
        for t in [t for t, v in customers.tokens.items() if v.get('customer_id') == c['id']]:
            customers.tokens.pop(t, None)
        customers.save(force=True)
    elif action in ('block', 'unblock'):
        c['blocked'] = action == 'block'
        customers.save(force=True)
    elif action == 'notify':
        app_notify(c, str(d.get('title') or 'Message from BPC')[:80], str(d.get('body') or '')[:300], '/app/#/notifications', 'info')
    elif action == 'delete':
        if float(c.get('balance') or 0) > 0.009 and not d.get('force'):
            return web.json_response({'error': 'Customer still has a balance of %.2f - refund it first or use force' % float(c['balance'])}, status=409)
        customers.customers.pop(c['id'], None)
        for t in [t for t, v in customers.tokens.items() if v.get('customer_id') == c['id']]:
            customers.tokens.pop(t, None)
        customers.save(force=True)
        await app_state.broadcast('customer_update', {'customer': {'id': c['id'], 'deleted': True}})
        return _app_json({'ok': True, 'deleted': c['id']})
    else:
        return web.json_response({'error': 'Unknown action'}, status=400)
    await app_state.broadcast('customer_update', {'customer': customers.admin_view(c)})
    return _app_json({'ok': True, 'customer': customers.admin_view(c)})


async def handle_app_admin_settings(request):
    if request.method == 'GET':
        return _app_json(app_settings.admin())
    d = await _app_body(request)
    app_settings.update(d)
    app_state.add_log('👤 APP', 'SYSTEM', 'AppSettingsChanged', {'promos': len(app_settings.data.get('promos') or []), 'tiers': [t['name'] for t in app_settings.tiers()]})
    return _app_json(app_settings.admin())


async def handle_app_admin_station_info(request):
    if request.method == 'GET':
        rows = []
        for s in app_state.station_records():
            info = station_info.data.get(s['id']) or {}
            rows.append({'id': s['id'], 'registration': s.get('registration_status'), 'online': bool(s.get('connected')), **{k: info.get(k) for k in ('name', 'address', 'hours', 'note', 'lat', 'lon', 'max_kw', 'hidden')}})
        return _app_json({'stations': rows})
    d = await _app_body(request)
    if d.get('demo'):
        n = station_info.fill_demo()
        return _app_json({'ok': True, 'filled': n})
    cp_id = str(d.get('id') or '').strip()
    if not cp_id:
        return web.json_response({'error': 'id required'}, status=400)
    station_info.set(cp_id, d)
    return _app_json({'ok': True, 'info': station_info.data.get(cp_id)})


async def handle_app_admin_push_broadcast(request):
    d = await _app_body(request)
    title = str(d.get('title') or '').strip()[:80]
    body = str(d.get('body') or '').strip()[:300]
    if not title:
        return web.json_response({'error': 'title required'}, status=400)
    n = 0
    for c in customers.customers.values():
        app_notify(c, title, body, str(d.get('url') or '/app/#/notifications'), 'info')
        n += 1
    return _app_json({'ok': True, 'customers': n})


# ---------------------------------------------------------------------------
# App shell (PWA): page, service worker, manifest, icons
# ---------------------------------------------------------------------------
async def handle_app_poster(request):
    """Printable poster: QR code + install steps so customers know where to get the app (Customers tab)."""
    url = _pay_base_url(request) + '/app/'
    svg = QrCode.encode(url, 'M').to_svg(scale=6, border=3)
    support = str(app_settings.data.get('support_phone') or '').strip()
    page = (APP_POSTER_TEMPLATE.replace('{{TITLE}}', html_escape('BPC EV app - install poster')).replace('{{BRAND}}', html_escape(BRAND_NAME))
            .replace('{{QR}}', svg).replace('{{URL}}', html_escape(url))
            .replace('{{SUPPORT}}', html_escape(('Help: ' + support) if support else 'Help: ask the station staff')))
    return web.Response(text=page, content_type='text/html')


async def handle_app_index(request):
    if request.path == '/app':
        raise web.HTTPFound('/app/')
    return web.Response(text=APP_PAGE_TEMPLATE, content_type='text/html',
                        headers={'Cache-Control': 'no-cache', 'Referrer-Policy': 'strict-origin-when-cross-origin'})


async def handle_app_sw(request):
    return web.Response(text=APP_SW_TEMPLATE, content_type='application/javascript', headers={'Cache-Control': 'no-cache', 'Service-Worker-Allowed': '/app/'})


async def handle_app_manifest(request):
    name = app_settings.data.get('app_name') or 'BPC EV'
    manifest = {
        'name': '%s - %s' % (name, BRAND_NAME), 'short_name': name, 'start_url': '/app/', 'scope': '/app/', 'display': 'standalone',
        'background_color': '#ffffff', 'theme_color': '#0a7a3c', 'lang': 'en', 'description': 'Find a BPC charger, pay and charge your EV.',
        'icons': [{'src': '/app/icon-192.png', 'sizes': '192x192', 'type': 'image/png'},
                  {'src': '/app/icon-512.png', 'sizes': '512x512', 'type': 'image/png'},
                  {'src': '/app/icon-512.png', 'sizes': '512x512', 'type': 'image/png', 'purpose': 'maskable'}],
    }
    return web.Response(text=json.dumps(manifest), content_type='application/manifest+json', headers={'Cache-Control': 'no-cache'})


async def handle_app_icon(request):
    name = request.match_info.get('name', '')
    b64 = APP_ICONS_B64.get(name)
    if not b64:
        return web.json_response({'error': 'not found'}, status=404)
    return web.Response(body=_pay_b64.b64decode(b64), content_type='image/png', headers={'Cache-Control': 'public, max-age=604800'})


async def app_flush_task():
    while True:
        try:
            await asyncio.sleep(10)
            customers.flush()
        except asyncio.CancelledError:
            customers.flush()
            raise
        except Exception as e:
            logger.error(f"app flush: {e}")


def app_register_routes(app):
    app.router.add_get('/app', handle_app_index)
    app.router.add_get('/app/', handle_app_index)
    app.router.add_get('/app/sw.js', handle_app_sw)
    app.router.add_get('/app/manifest.webmanifest', handle_app_manifest)
    app.router.add_get('/app/{name:(icon-192|icon-512|icon-64|apple-touch-icon)\\.png}', handle_app_icon)
    app.router.add_get('/app/tiles/{z}/{x}/{y}.png', handle_app_tile)
    app.router.add_post('/api/app/register', handle_app_register)
    app.router.add_post('/api/app/login', handle_app_login)
    app.router.add_post('/api/app/logout', handle_app_logout)
    app.router.add_get('/api/app/me', handle_app_me)
    app.router.add_post('/api/app/me', handle_app_me)
    app.router.add_get('/api/app/stations', handle_app_stations)
    app.router.add_get('/api/app/station/{cp_id}', handle_app_station)
    app.router.add_post('/api/app/charge', handle_app_charge)
    app.router.add_post('/api/app/topup', handle_app_topup)
    app.router.add_get('/api/app/sessions', handle_app_sessions)
    app.router.add_get('/api/app/wallet', handle_app_wallet)
    app.router.add_get('/api/app/notifications', handle_app_notifications)
    app.router.add_post('/api/app/notifications/read', handle_app_notifications)
    app.router.add_post('/api/app/push/subscribe', handle_app_push_subscribe)
    app.router.add_post('/api/app/push/unsubscribe', handle_app_push_subscribe)
    app.router.add_post('/api/app/push/test', handle_app_push_test)
    app.router.add_post('/api/app/promo/check', handle_app_promo_check)
    app.router.add_get('/api/app/admin/customers', handle_app_admin_customers)
    app.router.add_get('/api/app/admin/customer/{cid}', handle_app_admin_customer)
    app.router.add_post('/api/app/admin/customer/action', handle_app_admin_customer_action)
    app.router.add_get('/api/app/admin/settings', handle_app_admin_settings)
    app.router.add_post('/api/app/admin/settings', handle_app_admin_settings)
    app.router.add_get('/api/app/admin/station_info', handle_app_admin_station_info)
    app.router.add_post('/api/app/admin/station_info', handle_app_admin_station_info)
    app.router.add_post('/api/app/admin/push/broadcast', handle_app_admin_push_broadcast)
    app.router.add_get('/api/app/admin/poster', handle_app_poster)


APP_ICONS_B64 = {
    'icon-192.png': '',
    'icon-512.png': '',
    'apple-touch-icon.png': '',
    'icon-64.png': '',
}

# ============================================================================
# [MAP] Operator map tab: Leaflet (BSD-2-Clause, embedded) served from this file, station positions come from
#       station_info.json (shared with the BPC EV app), tiles through the app's tile proxy (/app/tiles/...).
# ============================================================================
import zlib as _map_zlib

_MAP_LEAFLET_CACHE: Dict[str, bytes] = {}


def _map_leaflet(kind: str) -> bytes:
    data = _MAP_LEAFLET_CACHE.get(kind)
    if data is None:
        data = _map_zlib.decompress(_pay_b64.b64decode(LEAFLET_B64[kind]))
        _MAP_LEAFLET_CACHE[kind] = data
    return data


async def handle_map_leaflet_js(request):
    return web.Response(body=_map_leaflet('js'), content_type='application/javascript',
                        headers={'Cache-Control': 'public, max-age=604800'})


async def handle_map_leaflet_css(request):
    return web.Response(body=_map_leaflet('css'), content_type='text/css', headers={'Cache-Control': 'public, max-age=604800'})


async def handle_map_config(request):
    """Tile layer + default view for the operator map (same settings as the customer app)."""
    pub = app_settings.public()
    m = pub.get('map') or {}
    return _app_json({'tile_url': m.get('tile_url') or APP_TILE_PROXY_URL, 'attribution': m.get('attribution') or '',
                      'center': m.get('center') or [27.4728, 89.6390], 'zoom': int(m.get('zoom') or 8), 'proxy': bool(m.get('proxy', True)),
                      'leaflet': LEAFLET_B64.get('version', '')})


def map_register_routes(app):
    app.router.add_get('/static/leaflet.js', handle_map_leaflet_js)
    app.router.add_get('/static/leaflet.css', handle_map_leaflet_css)
    app.router.add_get('/api/map/config', handle_map_config)


