# ============================================================================
# [CLOUD] OCPP on the web port: ws(s)://<host>/ocpp/<charge point id>
# A PaaS such as Render gives one public port (HTTPS 443 -> $PORT), so charge points connect through the web server;
# the OCPP server on --port keeps working for the LAN and for the built-in simulators.
# ============================================================================
class _WebOcppRequest:
    def __init__(self, path, headers):
        self.path = path
        self.headers = headers


class _WebOcppSocket:
    """The part of the websockets connection API that python-ocpp and on_ocpp_connect use, on top of aiohttp."""

    def __init__(self, ws, request):
        self._ws = ws
        self.path = request.path
        self.request = _WebOcppRequest(request.path, request.headers)
        peer = request.transport.get_extra_info('peername') if request.transport else None
        port = peer[1] if isinstance(peer, (tuple, list)) and len(peer) >= 2 else 0
        self.remote_address = (_client_ip(request), port)
        self.subprotocol = ws.ws_protocol

    async def recv(self):
        while True:
            msg = await self._ws.receive()
            if msg.type == aiohttp.WSMsgType.TEXT:
                return msg.data
            if msg.type == aiohttp.WSMsgType.BINARY:
                return bytes(msg.data).decode('utf-8', 'replace')
            if msg.type in (aiohttp.WSMsgType.CLOSE, aiohttp.WSMsgType.CLOSING, aiohttp.WSMsgType.CLOSED,
                            aiohttp.WSMsgType.ERROR):
                raise ConnectionError(f'OCPP websocket closed ({msg.type.name})')

    async def send(self, data):
        if self._ws.closed:
            raise ConnectionError('OCPP websocket closed')
        await self._ws.send_str(data if isinstance(data, str) else bytes(data).decode('utf-8'))

    async def close(self, code: int = 1000, reason: str = ''):
        await self._ws.close(code=code, message=str(reason or '').encode('utf-8')[:120])

    @property
    def closed(self) -> bool:
        return self._ws.closed

    @property
    def open(self) -> bool:
        return not self._ws.closed


async def handle_ocpp_web(request):
    """[CLOUD] OCPP 1.6-J over the web port (public path: charge points do not log in)."""
    if not request.match_info.get('cp_path', '').strip('/'):
        raise web.HTTPNotFound(text='Use /ocpp/<charge point id>')
    ws = web.WebSocketResponse(protocols=('ocpp1.6',), heartbeat=45)
    if not ws.can_prepare(request).ok:
        return web.Response(text='OCPP 1.6-J endpoint: connect a charge point to ws(s)://<this host>/ocpp/<id>\n',
                            content_type='text/plain')
    await ws.prepare(request)
    try:
        await on_ocpp_connect(_WebOcppSocket(ws, request))
    finally:
        if not ws.closed:
            await ws.close()
    return ws


# ============================================================================
# Main
# ============================================================================
async def main(ocpp_port: int, web_port: int, tls_cert: str = None, tls_key: str = None):
    # Start OCPP WebSocket server with ping settings
    # Note: Server-side ping is independent from CP's WebSocketPingInterval
    # การเปิด ping ฝั่งเซิร์ฟเวอร์ทำให้ตรวจจับตู้ที่หลุดแบบไม่ปิด connection อย่างถูกต้องได้
    ocpp_server = await websockets.serve(
        on_ocpp_connect,
        os.environ.get('CSMS_OCPP_BIND', '').strip() or '0.0.0.0',   # [CLOUD] 127.0.0.1 in the container
        ocpp_port,
        subprotocols=['ocpp1.6'],
        # เปิด server-side ping เพื่อตรวจจับตู้ที่หลุดแบบกะทันหัน (ไฟดับ/เน็ตหลุด/ถอดสาย)
        # ถ้าตู้ไม่ตอบ pong ภายใน ping_timeout เซิร์ฟเวอร์จะปิด connection -> เข้า finally
        # -> ตั้ง connected=False และลบออกจาก charge_points -> CSMS ขึ้น Offline ทันที
        ping_interval=30,   # ส่ง ping ทุก 30 วินาที
        ping_timeout=60     # ไม่ได้รับ pong ภายใน 60 วินาที ถือว่าตู้หลุด
    )
    logger.info(f"OCPP server started on ws://0.0.0.0:{ocpp_port}")
    
    # Setup web app (security headers + auth middleware: ต้อง login ก่อนเข้าใช้งาน)
    app = web.Application(middlewares=[security_headers_middleware, auth_middleware])
    app.router.add_get('/login', handle_login)
    app.router.add_post('/login', handle_login)
    app.router.add_get('/logout', handle_logout)
    app.router.add_get('/', handle_index)
    app.router.add_get('/api/charge_points', handle_api_charge_points)
    app.router.add_get('/api/stations', handle_api_stations)
    app.router.add_get('/static/bpc_logo.png', handle_static_logo)
    app.router.add_get('/favicon.ico', handle_static_logo)
    app.router.add_get('/api/logs', handle_api_logs)
    app.router.add_post('/api/command', handle_api_command)
    app.router.add_get('/ws', handle_websocket)
    app.router.add_get('/ocpp/{cp_path:.*}', handle_ocpp_web)   # [CLOUD] OCPP on the web port: ws(s)://<host>/ocpp/<id>
    app.router.add_get('/health', handle_health)
    app.router.add_post('/api/switch_version', handle_switch_version)
    
    # RFID Card Management API
    app.router.add_get('/api/rfid', handle_api_rfid_list)
    app.router.add_post('/api/rfid/add', handle_api_rfid_add)
    app.router.add_post('/api/rfid/delete', handle_api_rfid_delete)
    app.router.add_post('/api/rfid/import', handle_api_rfid_import)
    
    # CP Registration Management API
    app.router.add_get('/api/cp/registrations', handle_api_cp_registrations)
    app.router.add_post('/api/cp/set_status', handle_api_cp_set_status)
    app.router.add_post('/api/cp/delete', handle_api_cp_delete_registration)
    app.router.add_post('/api/cp/disconnect', handle_api_cp_disconnect)
    
    # Default Configuration API
    app.router.add_get('/api/config/defaults', handle_api_default_config)
    app.router.add_post('/api/config/restore', handle_api_restore_config)
    app.router.add_post('/api/config/batch', handle_api_set_config_batch)
    
    # OCPP Log Export API
    app.router.add_get('/api/logs/dates', handle_api_logs_dates)
    app.router.add_get('/api/logs/by_date', handle_api_logs_by_date)
    app.router.add_get('/api/logs/export', handle_api_logs_export)
    app.router.add_post('/api/logs/clear', handle_api_logs_clear)

    # Diagnostics Upload/Download API
    app.router.add_route('PUT', '/api/diagnostics/upload/{filename}', handle_diagnostics_upload)
    app.router.add_get('/api/diagnostics/list', handle_diagnostics_list)
    app.router.add_get('/api/diagnostics/files/{filename}', handle_diagnostics_download)
    
    # Log Viewer Page
    app.router.add_get('/api/ftp/download/{charger_id}', handle_ftp_download)
    pay_register_routes(app)   # [PAYMENT] customer pay page + Payments tab API
    app_register_routes(app)   # [APP] BPC EV customer app (PWA) + Customers tab API
    map_register_routes(app)   # [MAP] operator map tab (Leaflet assets + config)
    db_register_routes(app)   # [DB] database tab API (status / test / settings / export)
    
    # Start web server (รองรับ HTTPS ถ้ามี cert/key)
    global COOKIE_SECURE
    ssl_context = None
    if tls_cert and tls_key:
        import ssl
        ssl_context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        ssl_context.load_cert_chain(certfile=tls_cert, keyfile=tls_key)
        COOKIE_SECURE = True   # ใช้ HTTPS แล้ว -> ตั้ง cookie Secure
        logger.info("🔒 HTTPS เปิดใช้งาน (TLS) — cookie จะถูกตั้ง Secure flag")
    if (os.environ.get('CSMS_COOKIE_SECURE', '').strip() == '1'
            or os.environ.get('CSMS_PUBLIC_URL', '').strip().lower().startswith('https://')):
        COOKIE_SECURE = True   # [CLOUD] HTTPS ends at the proxy (Render) - the browser still talks https
        logger.info("🔒 Secure session cookie (public HTTPS address: %s)", os.environ.get('CSMS_PUBLIC_URL', '-'))
    if TRUST_PROXY:
        logger.info("☁️ Behind a reverse proxy: client IP from %s", CLIENT_IP_HEADER or 'X-Forwarded-For (first entry)')
    logger.info("🔌 OCPP also on the web port: ws(s)://<host>/ocpp/<CP_ID>")

    runner = web.AppRunner(app)
    await runner.setup()
    site = web.TCPSite(runner, '0.0.0.0', web_port, ssl_context=ssl_context)
    await site.start()
    asyncio.create_task(pay_watchdog())   # [PAYMENT] expiry / start retries / time-based budget / ledger flush
    asyncio.create_task(app_flush_task())   # [APP] customer store flush
    # [CLOUD] graceful stop: Render / Docker send SIGTERM before replacing the instance -> save the ledgers and the
    # database queue first, so a redeploy loses nothing
    try:
        import signal as _cloud_signal

        def _cloud_on_sigterm():
            logger.info('SIGTERM - saving data before exit')
            try:
                for _name in ('pay_ledger', 'customers'):
                    _store = globals().get(_name)
                    if _store is not None:
                        _store.flush()
                if DB is not None:
                    DB.flush(8)
            except Exception as _e:
                logger.error(f'saving data on SIGTERM failed: {_e}')
            os._exit(0)

        asyncio.get_running_loop().add_signal_handler(_cloud_signal.SIGTERM, _cloud_on_sigterm)
    except (NotImplementedError, RuntimeError, AttributeError, ValueError):
        pass                                     # Windows has no loop signal handlers (the launcher stops the child)

    scheme = 'https' if ssl_context else 'http'
    logger.info(f"🌐 Web UI started on {scheme}://0.0.0.0:{web_port}")
    if not ssl_context:
        logger.warning("⚠️ ใช้ HTTP (ไม่เข้ารหัส) — รหัสผ่าน/cookie ส่งแบบ plain text! "
                       "ควรใช้เฉพาะ LAN ที่เชื่อถือได้ หรือเปิด HTTPS ด้วย --tls-cert/--tls-key")

    logger.info(f"Loaded {len(app_state.rfid_cards)} RFID cards from database")
    logger.info(db_startup_summary())
    if AUTH['username'] and AUTH['password']:
        logger.info(f"🔐 Web UI login required — username: '{AUTH['username']}' (ตั้งค่าจาก env CSMS_USER/CSMS_PASS หรือ --username/--password)")
    else:
        logger.warning("🔐 ยังไม่ได้ตั้งค่า CSMS_USER/CSMS_PASS — จะ login ไม่ได้! กรุณา activate .venv หรือใส่ --username/--password ก่อนรัน")

    print(f"""
╔══════════════════════════════════════════════════════════════════════╗
║              OCPP 1.6 CSMS with Web UI                               ║
╠══════════════════════════════════════════════════════════════════════╣
║                                                                      ║
║  🌐 Web UI:     http://localhost:{web_port}                          ║
║  🔌 OCPP WS:    ws://localhost:{ocpp_port}/ocpp/<CP_ID>              ║
║  🎴 RFID Cards: {len(app_state.rfid_cards)} cards loaded             ║
║                                                                      ║
║  Example: Connect your CP to ws://YOUR_IP:{ocpp_port}/ocpp/MyCharger ║
║                                                                      ║
╚══════════════════════════════════════════════════════════════════════╝
    """)
    
    # Keep running
    await asyncio.Future()


def _run_v16():
    parser = argparse.ArgumentParser(description='OCPP 1.6 CSMS with Web UI')
    parser.add_argument('--port', type=int, default=9000, help='OCPP WebSocket port (default: 9000)')
    parser.add_argument('--web-port', type=int, default=8080, help='Web UI port (default: 8080)')
    parser.add_argument('--username', default=None, help='Web UI login username (override env CSMS_USER)')
    parser.add_argument('--password', default=None, help='Web UI login password (override env CSMS_PASS)')
    parser.add_argument('--tls-cert', default=os.environ.get('CSMS_TLS_CERT'), help='Path to TLS certificate (.pem) เพื่อเปิด HTTPS')
    parser.add_argument('--tls-key', default=os.environ.get('CSMS_TLS_KEY'), help='Path to TLS private key (.pem) เพื่อเปิด HTTPS')

    args = parser.parse_args()

    # ตั้งค่า credential สำหรับ login (argument มาก่อน env/ค่า default)
    if args.username:
        AUTH['username'] = args.username
    if args.password:
        AUTH['password'] = args.password

    try:
        asyncio.run(main(args.port, args.web_port, args.tls_cert, args.tls_key))
    except KeyboardInterrupt:
        print("\nServer stopped.")


