# <V201_BLOB_END>


def _v201_source() -> str:
    import base64, zlib
    return zlib.decompress(base64.b64decode(''.join(_V201_SOURCE_B64.split()))).decode('utf-8')


def _run_v201(argv):
    import types
    mod = types.ModuleType('csms_v201')
    mod.__file__ = os.path.abspath(__file__)
    mod.BPC_LOGO_B64 = BPC_LOGO_B64
    mod.BRAND_NAME = BRAND_NAME
    sys.modules['csms_v201'] = mod
    exec(compile(_v201_source(), 'csms_v201 (embedded)', 'exec'), mod.__dict__)
    sys.argv = [sys.argv[0]] + list(argv)
    logging.basicConfig(level=logging.INFO, format="%(asctime)s | %(levelname)s | %(message)s")
    try:
        asyncio.run(mod.run_server(mod.cli()))
    except KeyboardInterrupt:
        pass


def _extract_v201(path):
    Path(path).write_text(_v201_source(), encoding='utf-8')
    print(f'✅ เขียนโค้ด OCPP 2.0.1 ออกไปที่ {path}')


def _embed_v201(path):
    import base64, zlib, re, textwrap
    code = Path(path).read_text(encoding='utf-8')
    compile(code, path, 'exec')                       # ตรวจ syntax ก่อนฝัง
    blob = base64.b64encode(zlib.compress(code.encode('utf-8'), 9)).decode()
    blob = '\n'.join(textwrap.wrap(blob, 100))
    me = Path(__file__).resolve()
    text = me.read_text(encoding='utf-8')
    new = re.sub(r'(# <V201_BLOB_BEGIN>\r?\n_V201_SOURCE_B64 = """\r?\n).*?(\r?\n"""\r?\n# <V201_BLOB_END>)',
                 lambda m: m.group(1) + blob + m.group(2), text, count=1, flags=re.S)
    me.with_suffix('.py.bak').write_text(text, encoding='utf-8')
    me.write_text(new, encoding='utf-8')
    print(f'✅ ฝังโค้ด {path} เข้า {me.name} แล้ว (สำรองไฟล์เดิมไว้ที่ {me.name}.bak)')


# ############################################################################
#  ตัวเปิดหลัก: รัน CSMS ทีละเวอร์ชัน และสลับ 1.6 <-> 2.0.1 เมื่อกดปุ่มในหน้าเว็บ
#  (แต่ละเวอร์ชันรันเป็น process ลูกของไฟล์นี้เอง เพื่อให้ปล่อยพอร์ตและล้าง state สะอาด)
# ############################################################################
_STATE_FILE = APP_DIR / '.csms_last_version'
_OTHER = {'1.6': '2.0.1', '2.0.1': '1.6'}


def _child_command(version, args):
    if FROZEN:
        cmd = [sys.executable, '--csms-child', version]              # the .exe re-runs itself
    else:
        cmd = [sys.executable, os.path.abspath(__file__), '--csms-child', version]
    cmd += ['--port', str(args.port), '--web-port', str(args.web_port)]
    if version == '2.0.1':
        # 2.0.1 ฟังเฉพาะ 127.0.0.1 เป็นค่าเริ่มต้น -> ตั้งให้เหมือน 1.6 (ทุก interface) เพื่อให้ Charger ใน LAN ต่อได้
        cmd += ['--host', args.ocpp_host, '--web-host', args.web_host]
    if args.tls_cert and args.tls_key:
        if version == '1.6':
            cmd += ['--tls-cert', args.tls_cert, '--tls-key', args.tls_key]
        else:
            cmd += ['--web-tls-cert', args.tls_cert, '--web-tls-key', args.tls_key]
    return cmd


def _load_launcher_config() -> dict:
    try:
        data = json.loads(CONFIG_FILE.read_text(encoding='utf-8'))
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


def _save_launcher_config(data: dict) -> None:
    try:
        CONFIG_FILE.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding='utf-8')
    except OSError as exc:
        print(f'⚠️  cannot write {CONFIG_FILE}: {exc}')


def _open_browser_when_ready(url: str, health_url: str, timeout: float = 40.0) -> None:
    """Background thread: wait until the Web UI answers, then open the default browser once."""
    import threading, time as _time, urllib.request, webbrowser, ssl as _ssl

    def worker():
        ctx = _ssl._create_unverified_context() if health_url.startswith('https') else None
        deadline = _time.monotonic() + timeout
        while _time.monotonic() < deadline:
            try:
                with urllib.request.urlopen(health_url, timeout=2, context=ctx) as resp:
                    if resp.status == 200:
                        break
            except Exception:
                _time.sleep(0.5)
        else:
            return
        try:
            webbrowser.open(url)
        except Exception:
            pass

    threading.Thread(target=worker, daemon=True).start()


# --- discovery: lets the Virtual Charger (and other tools) find this CSMS without typing an address ---------
DISCOVERY_PORT = 9077                                   # UDP; request/reply, same LAN (broadcast) or same PC
DISCOVERY_REQUEST = b'FLEXXFAST-CSMS-DISCOVER'
RUNTIME_FILE = APP_DIR / 'csms_runtime.json'            # ports of the running CSMS, for programs in the same folder


def _discovery_info(args, runtime: dict) -> dict:
    import socket
    return {'service': 'flexxfast-csms', 'ocpp_port': args.port, 'web_port': args.web_port,
            'ocpp_version': runtime.get('version', '1.6'), 'tls': bool(args.tls_cert and args.tls_key),
            'host': socket.gethostname(), 'pid': os.getpid(), 'started': runtime.get('started', '')}


def _write_runtime_file(args, runtime: dict) -> None:
    try:
        RUNTIME_FILE.write_text(json.dumps(_discovery_info(args, runtime), indent=2), encoding='utf-8')
    except OSError:
        pass


def _remove_runtime_file() -> None:
    try:
        if RUNTIME_FILE.exists() and json.loads(RUNTIME_FILE.read_text(encoding='utf-8')).get('pid') == os.getpid():
            RUNTIME_FILE.unlink()
    except (OSError, ValueError):
        pass


def _start_discovery_responder(args, runtime: dict) -> None:
    """Background thread answering UDP discovery requests with this CSMS's ports (reply goes to the sender)."""
    import socket, threading

    def worker():
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            sock.bind(('', DISCOVERY_PORT))
        except OSError as exc:
            print(f'⚠️  discovery responder not started (UDP {DISCOVERY_PORT}): {exc}')
            return
        while True:
            try:
                data, addr = sock.recvfrom(1024)
                if data.strip() == DISCOVERY_REQUEST:
                    sock.sendto(json.dumps(_discovery_info(args, runtime)).encode('utf-8'), addr)
            except OSError:
                continue

    threading.Thread(target=worker, daemon=True, name='csms-discovery').start()


def _free_port(port: int, label: str, tries: int = 20) -> int:
    """Return `port` if it can be listened on (same asyncio path aiohttp/websockets use), else the next free one."""
    async def usable(candidate: int) -> bool:
        try:
            server = await asyncio.start_server(lambda r, w: w.close(), host='0.0.0.0', port=candidate)
        except OSError:
            return False
        server.close()
        await server.wait_closed()
        return True

    for candidate in range(port, port + tries):
        if asyncio.run(usable(candidate)):
            if candidate != port:
                print(f'⚠️  {label} port {port} is in use -> using {candidate} instead')
            return candidate
    return port


# [SINGLE] one CSMS per installation
def _running_instance():
    """The CSMS already running from this folder (csms_runtime.json + an answer on /health), or None."""
    import urllib.request, ssl as _ssl
    try:
        info = json.loads(RUNTIME_FILE.read_text(encoding='utf-8'))
        port = int(info.get('web_port') or 0)
    except (OSError, ValueError, TypeError, AttributeError):
        return None
    if not port:
        return None
    scheme = 'https' if info.get('tls') else 'http'
    ctx = _ssl._create_unverified_context() if scheme == 'https' else None
    try:
        with urllib.request.urlopen(f'{scheme}://127.0.0.1:{port}/health', timeout=2, context=ctx) as resp:
            data = json.loads(resp.read().decode('utf-8', 'replace') or '{}')
            if resp.status != 200 or data.get('status') != 'ok':
                return None
    except Exception:
        return None
    info['url'] = f'{scheme}://localhost:{port}/'
    return info


def _launcher_main():
    import subprocess, signal, time
    ap = argparse.ArgumentParser(description='Flexxfast CSMS (OCPP 1.6 <-> 2.0.1)')
    ap.add_argument('--start', choices=['1.6', '2.0.1'], help='เวอร์ชันที่จะเปิดก่อน (ค่าเริ่มต้น: ที่ใช้ล่าสุด)')
    ap.add_argument('--port', type=int, default=9000, help='OCPP WebSocket port (default: 9000)')
    ap.add_argument('--web-port', type=int, default=8080, help='Web UI port (default: 8080)')
    ap.add_argument('--username', default=None, help='Web UI login username (override env CSMS_USER)')
    ap.add_argument('--password', default=None, help='Web UI login password (override env CSMS_PASS)')
    ap.add_argument('--tls-cert', default=os.environ.get('CSMS_TLS_CERT'), help='Path to TLS certificate (.pem) เพื่อเปิด HTTPS')
    ap.add_argument('--tls-key', default=os.environ.get('CSMS_TLS_KEY'), help='Path to TLS private key (.pem) เพื่อเปิด HTTPS')
    ap.add_argument('--ocpp-host', default='0.0.0.0', help='OCPP bind address ของ 2.0.1 (default 0.0.0.0)')
    ap.add_argument('--web-host', default='0.0.0.0', help='Web UI bind address ของ 2.0.1 (default 0.0.0.0)')
    ap.add_argument('--no-browser', action='store_true', help='ไม่ต้องเปิด browser อัตโนมัติเมื่อ Web UI พร้อม')
    ap.add_argument('--new-instance', action='store_true',
                    help='start another CSMS even when one is already running from this folder')
    ap.add_argument('--extract-v201', metavar='FILE', help='แตกโค้ด OCPP 2.0.1 ที่ฝังไว้ออกมาเป็นไฟล์ แล้วจบ')
    ap.add_argument('--embed-v201', metavar='FILE', help='ฝังโค้ด OCPP 2.0.1 จากไฟล์กลับเข้าไฟล์นี้ แล้วจบ')
    args = ap.parse_args()

    if args.extract_v201:
        _extract_v201(args.extract_v201)
        return 0
    if args.embed_v201:
        _embed_v201(args.embed_v201)
        return 0

    # one CSMS per installation: when it already runs (desktop icon clicked again), open it instead of a second copy
    if not args.new_instance and args.port == 9000 and args.web_port == 8080:
        running = _running_instance()
        if running:
            print(f"\n✅ Flexxfast CSMS is already running (pid {running.get('pid')}): {running['url']}\n"
                  f"   OCPP: ws://<IP>:{running.get('ocpp_port')}/ocpp/<ID>   (start with --new-instance for a second copy)\n")
            if not args.no_browser:
                try:
                    import webbrowser
                    webbrowser.open(running['url'])
                except Exception:
                    pass
            import time as _single_time
            _single_time.sleep(5)
            return 0

    env = dict(os.environ, CSMS_LAUNCHER='1', PYTHONIOENCODING='utf-8')
    if args.username:
        env['CSMS_USER'] = args.username          # ส่งผ่าน env ไม่ให้โชว์ใน process list
    if args.password:
        env['CSMS_PASS'] = args.password

    # csms_config.json next to the program: login + ports (used when nothing was given on the command line)
    saved = _load_launcher_config()
    if not env.get('CSMS_USER') or not env.get('CSMS_PASS'):
        if saved.get('username') and saved.get('password'):
            env['CSMS_USER'], env['CSMS_PASS'] = str(saved['username']), str(saved['password'])
        elif sys.stdin is not None and sys.stdin.isatty():
            print('\n🔐 First run: choose the Web UI login (saved to csms_config.json next to this program)')
            try:
                user = input('   Username [admin]: ').strip() or 'admin'
                password = input('   Password: ').strip()
                while not password:
                    password = input('   Password (required): ').strip()
            except (EOFError, KeyboardInterrupt):
                user, password = '', ''
            if user and password:
                env['CSMS_USER'], env['CSMS_PASS'] = user, password
                saved.update({'username': user, 'password': password})
                _save_launcher_config(saved)
    if not env.get('CSMS_USER') or not env.get('CSMS_PASS'):
        print('⚠️  ยังไม่ได้ตั้ง CSMS_USER / CSMS_PASS -> จะ login หน้าเว็บไม่ได้')
    if args.web_port == 8080 and str(saved.get('web_port', '')).isdigit():
        args.web_port = int(saved['web_port'])
    if args.port == 9000 and str(saved.get('ocpp_port', '')).isdigit():
        args.port = int(saved['ocpp_port'])
    args.web_port = _free_port(args.web_port, 'Web UI')
    args.port = _free_port(args.port, 'OCPP')
    open_browser = (not args.no_browser) and str(saved.get('open_browser', 'true')).lower() != 'false'

    try:
        last = _STATE_FILE.read_text(encoding='utf-8').strip()
    except OSError:
        last = ''
    version = args.start or (last if last in _OTHER else '1.6')
    previous = None
    current = {'proc': None}
    browser_opened = False
    runtime = {'version': version, 'started': datetime.now().isoformat(timespec='seconds')}
    _start_discovery_responder(args, runtime)       # Virtual Charger finds us by UDP broadcast ...
    _write_runtime_file(args, runtime)              # ... or by this file when it sits in the same folder

    def on_term(signum, frame):
        p = current['proc']
        if p and p.poll() is None:
            p.terminate()
            try:
                p.wait(timeout=10)
            except subprocess.TimeoutExpired:
                p.kill()
        _remove_runtime_file()
        sys.exit(0)

    if hasattr(signal, 'SIGTERM'):
        signal.signal(signal.SIGTERM, on_term)

    try:
        while True:
            try:
                _STATE_FILE.write_text(version, encoding='utf-8')
            except OSError:
                pass
            runtime['version'] = version
            _write_runtime_file(args, runtime)
            print('\n' + '=' * 64 + f'\n  ▶ CSMS OCPP {version}  |  Web: http://localhost:{args.web_port}'
                  f'  |  OCPP: ws://<IP>:{args.port}/ocpp/<ID>\n' + '=' * 64, flush=True)
            started = time.monotonic()
            proc = subprocess.Popen(_child_command(version, args), env=env)
            current['proc'] = proc
            if open_browser and not browser_opened:
                # open the default browser once the Web UI is up (only on the first start, not on version switches)
                browser_opened = True
                scheme = 'https' if (args.tls_cert and args.tls_key) else 'http'
                _open_browser_when_ready(f'{scheme}://localhost:{args.web_port}/',
                                         f'{scheme}://127.0.0.1:{args.web_port}/health')
            try:
                code = proc.wait()
            except KeyboardInterrupt:
                print('\n⏹  กำลังปิด CSMS...')
                try:
                    proc.wait(timeout=5)
                except (subprocess.TimeoutExpired, KeyboardInterrupt):
                    proc.kill()
                return 0

            if code == CSMS_SWITCH_EXIT_CODE:
                previous, version = version, _OTHER[version]
                print(f'\n🔀 Switching OCPP {previous} -> {version}', flush=True)
                time.sleep(1)
                continue
            if previous and code != 0 and time.monotonic() - started < 20:
                print(f'\n❌ OCPP {version} เปิดไม่สำเร็จ (exit code {code}) -> กลับไปใช้ OCPP {previous}', flush=True)
                version, previous = previous, None
                time.sleep(1)
                continue
            print(f'\nCSMS OCPP {version} หยุดทำงาน (exit code {code})')
            return code
    finally:
        _remove_runtime_file()


if __name__ == '__main__':
    if len(sys.argv) >= 3 and sys.argv[1] == '--csms-child':
        _child_version = sys.argv[2]
        _child_args = sys.argv[3:]
        if _child_version == '2.0.1':
            _run_v201(_child_args)
        else:
            sys.argv = [sys.argv[0]] + _child_args
            _run_v16()
    else:
        sys.exit(_launcher_main())
